window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[151]={"id":"151","numero":151,"titre":"Méningites · Méningo-encéphalites · Abcès cérébral","objectifs":[{"id":"151-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez l'adulte et en pédiatrie, d'un abcès cérébral","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">méninges</span> sont les <strong>3 membranes</strong> qui enveloppent l'encéphale et la moelle. De dehors en dedans : la <span class=\"kw-def\">dure-mère</span> (couche superficielle résistante, accolée à l'os), l'<span class=\"kw-def\">arachnoïde</span> (couche moyenne) et la <span class=\"kw-def\">pie-mère</span> (couche interne recouvrant le cerveau). La <strong>pachyméninge</strong> désigne la dure-mère ; la <strong>leptoméninge</strong> regroupe arachnoïde et pie-mère. L'<span class=\"kw-def\">espace sous-arachnoïdien</span>, situé entre arachnoïde et pie-mère, contient le <span class=\"kw-bio\">liquide cérébrospinal (LCS)</span>.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Méningite</span></td><td><strong>Réaction <span class=\"kw-etio\">inflammatoire</span></strong> de l'espace méningé, le plus souvent d'origine <span class=\"kw-etio\">infectieuse</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Méningo-encéphalite</span></td><td>Inflammation des <strong>méninges ET de l'encéphale</strong> (atteinte parenchymateuse associée).</td></tr>\n          <tr><td><span class=\"kw-def\">Abcès cérébral</span></td><td><strong>Collection suppurée</strong> développée au sein du <strong>parenchyme cérébral</strong> — à distinguer de l'<span class=\"kw-etio\">empyème</span> (collection suppurée de l'espace sous-dural ou extra-dural).</td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-clinique\">abcès</span> cérébral se constitue en <strong>2 étapes</strong> : 1) phase d'<span class=\"kw-def\">encéphalite pré-suppurative</span> (centre nécrotique, germe et <span class=\"kw-clinique\">œdème</span>) ; 2) <span class=\"kw-def\">stade d'abcès</span> avec formation d'une <strong>capsule de gliose</strong>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Méningite</span></th><th>Profil épidémiologique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Virale</span></td><td>Le plus souvent <strong>bénigne</strong> ; fréquente chez l'enfant et l'adulte jeune.</td></tr>\n          <tr><td><span class=\"kw-etio\">Bactérienne</span></td><td>Plus <span class=\"kw-alerte\">grave</span> : <span class=\"kw-chiffre\">20 %</span> de <span class=\"kw-def\">mortalité</span>, <span class=\"kw-chiffre\">30 %</span> de séquelles ; plus fréquente après <span class=\"kw-chiffre\">65 ans</span>.</td></tr>\n        </tbody>\n      </table>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/post-dural-puncture-headache","label":"Radiopaedia : Post-dural puncture headache"},{"href":"https://radiopaedia.org/articles/viral-encephalitides","label":"Radiopaedia : Viral encephalitides"},{"href":"https://radiopaedia.org/articles/cerebral-abscess-1","label":"Radiopaedia : Cerebral abscess"},{"href":"https://radiopaedia.org/articles/herpes-simplex-encephalitis","label":"Radiopaedia : Herpes simplex encephalitis"}]},{"id":"151-2","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir suspecter cliniquement un syndrome méningé fébrile et connaître les particularités sémiologiques en fonction du terrain (enfant, personne âgée)","contenu":"<p>Le <span class=\"kw-def\">syndrome méningé fébrile</span> typique associe <strong>au moins 2</strong> éléments parmi : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">raideur de nuque</span>, <span class=\"kw-clinique\">céphalée</span> et <span class=\"kw-clinique\">altération de la conscience</span>. La recherche d'un <span class=\"kw-clinique\">purpura</span> est obl<span class=\"kw-chiffre\">iga</span>toire, sur un patient <strong>entièrement déshabillé</strong>.</p>\n      <table >\n        <thead><tr><th>Composante</th><th>Caractéristiques sémiologiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Céphalée</span></td><td>Quasi-constante : précoce, récente, inhabituelle, mal soulagée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antalgiques</span> habituels ; topographie <strong>en casque</strong> ou diffuse ; aggravée par les mouvements de la tête, l'examen, la lumière (<span class=\"kw-clinique\">photophobie</span>) et le bruit (<span class=\"kw-clinique\">phonophobie</span>).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Vomissements</span></td><td>En jet (ou <span class=\"kw-clinique\">nausées</span>), inconstants, précoces ; favorisés par <span class=\"kw-clinique\">les</span> changements de position ; peuvent soulager la <span class=\"kw-clinique\">céphalée</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Raideur méningée</span></td><td>Attitude en <strong>« chien de fusil »</strong> ; résistance invincible et douloureuse à la flexion de la nuque ; rotation et latéralité conservées mais douloureuses ; signe de <span class=\"kw-clinique\">Kernig</span> (la flexion des cuisses sur le bassin jambes étendues obl<span class=\"kw-chiffre\">ige</span> à fléchir <span class=\"kw-clinique\">les</span> jambes) ; signe de <span class=\"kw-clinique\">Brudzinski</span> (la flexion passive de la nuque entraîne la flexion des 2 membres inférieurs ; la flexion passive d'une hanche entraîne celle du <strong>membre inférieur controlatéral</strong>).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Autres signes</span></td><td>Raie méningitique de <span class=\"kw-clinique\">Trousseau</span> ; <span class=\"kw-clinique\">hyperesthésie cutanée</span> diffuse ; <span class=\"kw-clinique\">ROT vifs</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Particularités de <span class=\"kw-def\">terrain</span>.</strong> Chez le <strong>sujet âgé</strong>, <span class=\"kw-clinique\">les</span> signes sont plus frustes, le <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span> est souvent au 2ⁿᵈ plan, et le tableau peut être dominé par des <span class=\"kw-clinique\">troubles du comportement</span> ou des <span class=\"kw-clinique\">signes focaux</span>. Chez le <strong>nourrisson</strong>, le <span class=\"kw-def\">syndrome méningé</span> est souvent trompeur.</div>\n      <p><strong>Diagnostics à évoquer</strong> devant un <span class=\"kw-def\">syndrome méningé</span> : <span class=\"kw-etio\">méningites</span> et <span class=\"kw-etio\">méningo-encéphalites</span>, <span class=\"kw-alerte\">hémorragie méningée</span>, <span class=\"kw-def\">méningisme</span> (symptômes évocateurs sans atteinte <span class=\"kw-etio\">inflammatoire</span> des méninges).</p>","frequence":3},{"id":"151-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir identifier les éléments d'un syndrome encéphalitique et savoir évoquer une méningo-encéphalite herpétique","contenu":"<p>Le <span class=\"kw-def\">syndrome encéphalitique</span> regroupe <span class=\"kw-clinique\">les</span> <strong>signes neurologiques centraux</strong> qui distinguent la <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> de la <span class=\"kw-def\">méningite</span>. Cette distinction se fait sur la <strong>clinique</strong>, jamais sur le <span class=\"kw-bio\">LCS</span>.</p>\n      <table >\n        <thead><tr><th>Composante</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Troubles de la vigilance</span></td><td>Quasi-constants, fluctuants (de l'<span class=\"kw-clinique\">obnubilation</span> au <span class=\"kw-clinique\">coma</span>) ; souvent associés à des troubles neurovégétatifs (irrégularité du pouls, de la PA, de la température).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Manifestations épileptiques</span></td><td>Plus souvent partielles que généralisées, <span class=\"kw-alerte\">état de mal</span> possible ; souvent temporales dans l'herpès (illusions, <span class=\"kw-clinique\">hallucinations</span> olfactives, gustatives ou auditives).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles des fonctions supérieures</span></td><td><span class=\"kw-def\">Syndrome confusionnel</span>, bradypsychie, troubles du comportement ; troubles mnésiques (<strong>oubli à mesure</strong>) ; troubles du langage (manque du mot, <span class=\"kw-clinique\">aphasie</span> amnésique).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Autres</span></td><td>Mouvements anormaux ; signes de <span class=\"kw-clinique\">focalisation</span> (<span class=\"kw-clinique\">déficit moteur</span>, atteinte des nerfs crâniens).</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Définition formelle d'une <span class=\"kw-def\">encéphalite</span></strong> : inflammation du parenchyme et dysfonction neurologique = <span class=\"kw-chiffre\">≥ 1</span> élément parmi {altération de conscience ; <span class=\"kw-clinique\">confusion</span> ou <span class=\"kw-clinique\">désorientation</span> ; troubles mnésiques ; léthargie ; modification de personnalité ou du comportement} <strong>ET</strong> <span class=\"kw-chiffre\">≥ 2</span> éléments parmi {<span class=\"kw-clinique\">fièvre ≥ 38 °C</span> ; crise d'<span class=\"kw-etio\">épilepsie</span> ; déficit focal ; <span class=\"kw-bio\">pléiocytose LCS ≥ 5 éléments</span> ; anomalies <span class=\"kw-bio\">EEG</span> ; anomalies d'<span class=\"kw-imagerie\">imagerie</span>}.</p>\n      <div class=\"callout callout-warn\"><strong>Évoquer une <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> herpétique.</strong> La <span class=\"kw-etio\">méningo-encéphalite herpétique</span> doit être évoquée devant toute <span class=\"kw-clinique\">céphalée fébrile</span>, toute <span class=\"kw-clinique\">confusion fébrile</span>, tout <span class=\"kw-alerte\">coma fébrile</span>, tout tableau neurologique aigu ou subaigu fébrile polymorphe. <span class=\"kw-etio\">HSV</span> est la 1ʳᵉ cause d'<span class=\"kw-def\">encéphalite</span> <span class=\"kw-etio\">virale</span> (~<span class=\"kw-chiffre\">1/3</span> des cas) — c'est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique</span>.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/151/irm-flair-encephalite-herpetique.png\" alt=\"IRM cérébrale axiale FLAIR : hypersignal cortico-sous-cortical temporal interne évocateur de méningo-encéphalite herpétique\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM FLAIR</span> : hypersignal <span class=\"kw-imagerie\">temporal interne</span> (atteinte limbique), typique de la <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> herpétique. Source : fiche source EDN item 151.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus · 105 — Epilepsie</em></p>","frequence":3},{"id":"151-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques détaillées des différentes étiologies infectieuses des méningites purulentes chez l'enfant et l'adulte","contenu":"<p>Trois germes dominent <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">méningites purulentes</span> de l'enfant et de l'adulte. Leur présentation clinique oriente le diagnostic.</p>\n      <table >\n        <thead><tr><th>Germe</th><th><span class=\"kw-def\">Terrain</span> et clinique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Pneumocoque</span><br>(<em>Streptococcus pneumoniae</em>)</td><td><strong><span class=\"kw-def\">Terrain</span> :</strong> 1ʳᵉ cause chez l'adulte (~<span class=\"kw-chiffre\">700 cas/an</span>), <span class=\"kw-def\">pronostic</span> le plus grave ; sujet âgé, non vacciné, <span class=\"kw-def\">comorbidité</span> (<span class=\"kw-def\">diabète</span>, éthylisme, myélome), immunodépression (<span class=\"kw-etio\">alcoolisme</span>, <span class=\"kw-clinique\">asplénie</span>, <span class=\"kw-etio\">VIH</span>, hypogammaglobulinémie), <span class=\"kw-clinique\">brèche ostéo-méningée</span>.<br><strong>Clinique :</strong> infection ORL ou pulmonaire récente (otite, sinusite, <span class=\"kw-etio\">pneumonie</span>) ; début <strong>brutal</strong> ; <span class=\"kw-def\">syndrome méningé</span> franc avec <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">frissons</span> ; <span class=\"kw-alerte\">signes neurologiques de focalisation fréquents</span> ; <span class=\"kw-clinique\">coma</span>, <span class=\"kw-clinique\">convulsions</span> ; <span class=\"kw-clinique\">purpura</span> possible mais rare.</td></tr>\n          <tr><td><span class=\"kw-etio\">Méningocoque</span><br>(<em>Neisseria meningitidis</em>)</td><td><strong><span class=\"kw-def\">Terrain</span> :</strong> 2ᵉ cause chez l'adulte, <strong>1ʳᵉ cause chez le sujet jeune (<span class=\"kw-chiffre\">15-24 ans</span>)</strong> ; sujet jeune non immun, saison hivernale, cas groupés ; si terrain particulier — déficit en <span class=\"kw-bio\">complément</span>, asplénie.<br><strong>Clinique :</strong> début brutal, <span class=\"kw-def\">syndrome méningé</span> franc, <strong>pas de signe de focalisation</strong> ; arguments — rhinopharyngite inaugurale, herpès nasolabial, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-alerte\">purpura pétéchial</span> voire <span class=\"kw-alerte\">purpura extensif nécrotique</span> (<span class=\"kw-clinique\">purpura</span> fulminans).</td></tr>\n          <tr><td><span class=\"kw-etio\">Haemophilus influenzae</span></td><td>1ʳᵉ cause de <span class=\"kw-def\">méningite</span> <span class=\"kw-etio\">bactérienne</span> du <strong>nourrisson et de l'enfant &lt;<span class=\"kw-chiffre\"> 6 ans</span> non vacciné</strong> ; manifestations associées possibles — otite, épiglottite, arthrite, pneumopathie.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Germe prédominant selon l'âge.</strong> <span class=\"kw-chiffre\">&lt; 2-3 mois</span> : <span class=\"kw-etio\">streptocoque</span> du groupe B puis <span class=\"kw-etio\">E. coli</span> ; <span class=\"kw-chiffre\">2-12 mois</span> : <span class=\"kw-etio\">pneumocoque</span> ; <span class=\"kw-chiffre\">1-24 ans</span> : <span class=\"kw-etio\">méningocoque</span> ; <span class=\"kw-chiffre\">&gt; 24 ans</span> : <span class=\"kw-etio\">pneumocoque</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 148 — Infection naso-sinusiennes</em></p>","frequence":3},{"id":"151-5","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir suspecter cliniquement un abcès cérébral","contenu":"<p>L'<span class=\"kw-def\">abcès cérébral</span> s'installe le plus souvent sur un mode <strong>subaigu</strong>, sur <span class=\"kw-chiffre\">1 à 2 semaines</span> (vitesse intermédiaire entre l'<span class=\"kw-etio\">AVC</span> et la tumeur) ; parfois plus progressif (syndrome <span class=\"kw-etio\">tumoral</span> en tache d'huile) ou brutal.</p>\n      <p><strong>Manifestations cliniques</strong>, à divers degrés :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">AEG</span> et <span class=\"kw-clinique\">fièvre</span> <strong>inconstantes</strong> — <span class=\"kw-clinique\">fièvre</span> présente dans ~<span class=\"kw-chiffre\">50 %</span> des cas seulement.</li>\n        <li><span class=\"kw-alerte\">Syndrome d'HTIC</span> si <span class=\"kw-clinique\">lésion</span> volumineuse.</li>\n        <li>Signes neurologiques centraux : <span class=\"kw-clinique\">déficit localisateur</span>, <span class=\"kw-clinique\">crises épileptiques</span> focales ou généralisées, <span class=\"kw-clinique\">confusion</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> La <span class=\"kw-alerte\">fièvre absente n'élimine pas</span> un <span class=\"kw-clinique\">abcès</span> cérébral. Localisation par ordre de fréquence : lobe <strong>frontal</strong> &gt; <strong>temporal</strong> &gt; <strong>pariétal</strong>. Affection rare (<span class=\"kw-def\">incidence</span> ~<span class=\"kw-chiffre\">1/100 000/an</span>), <span class=\"kw-def\">morbidité</span> <span class=\"kw-chiffre\">20-30 %</span>, <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">15 %</span>.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/151/irm-diffusion-abces-cerebral.png\" alt=\"IRM cérébrale séquence de diffusion : lésion arrondie avec restriction de diffusion au centre, évocatrice d'abcès cérébral\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM diffusion</span> : <span class=\"kw-clinique\">lésion</span> arrondie avec <span class=\"kw-imagerie\">restriction centrale (ADC bas)</span> — la cocarde en <span class=\"kw-imagerie\">diffusion</span> distingue l'<span class=\"kw-clinique\">abcès</span> de la <span class=\"kw-clinique\">nécrose</span> <span class=\"kw-etio\">tumorale</span> (ADC haut). Source : fiche source EDN item 151.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"151-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les éléments de physiopathologie des méningites, des méningo-encéphalites et des abcès cérébraux","contenu":"<p><strong>Méningites — <span class=\"kw-def\">physiopathologie</span> en 2 temps.</strong></p>\n      <ul>\n        <li><strong>1) <span class=\"kw-bio\">Envahissement</span> <span class=\"kw-etio\">bactérien</span></strong> quasi-exclusivement par <span class=\"kw-def\">voie hématogène</span> vers <span class=\"kw-clinique\">les</span> espaces méningés et le <span class=\"kw-bio\">LCS</span>, qui est <strong>dépourvu d'activité bactéricide naturelle</strong> (contrairement au sérum).</li>\n        <li><strong>2) Réponse de l'hôte délétère</strong> : production de <span class=\"kw-def\">cytokines</span> in situ → inflammation méningée → <span class=\"kw-alerte\">œdème cérébral</span> et <span class=\"kw-ttt\">réduction</span> des flux vasculaires cérébraux → <span class=\"kw-alerte\">ischémie</span> et séquelles.</li>\n      </ul>\n      <p><strong>Méningo-encéphalites.</strong> <span class=\"kw-imagerie\">Diffusion</span> du germe à l'encéphale par <span class=\"kw-def\">voie hématogène</span> (exemple : <span class=\"kw-etio\">Listeria</span>) ou par <span class=\"kw-def\">voie neuronale</span> (exemple : <span class=\"kw-etio\">HSV</span>, rage).</p>\n      <p><strong><span class=\"kw-clinique\">Abcès</span> cérébral.</strong> Constitution en 2 étapes (<span class=\"kw-def\">encéphalite</span> pré-suppurative → <span class=\"kw-clinique\">abcès</span> avec <strong>capsule de gliose</strong>). Voies de contamination :</p>\n      <table >\n        <thead><tr><th>Voie</th><th>Fréquence et exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Contiguïté</span></td><td>~<span class=\"kw-chiffre\">50 %</span> : foyer ORL, ostéite crânienne, thrombophlébite septique.</td></tr>\n          <tr><td><span class=\"kw-def\">Voie hématogène</span></td><td>~<span class=\"kw-chiffre\">30 %</span> : foyer dentaire, <span class=\"kw-etio\">endocardite</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Post-traumatique / post-chirurgicale</span></td><td>~<span class=\"kw-chiffre\">10 %</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Porte d'entrée inconnue</span></td><td>~<span class=\"kw-chiffre\">10 %</span>.</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"151-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies et l'épidémiologie bactériennes et virales des méningites en fonction de l'analyse cytochimique du liquide cérébro-spinal (LCS) et de l'âge du patient","contenu":"<p>L'<strong>analyse cytochimique du <span class=\"kw-bio\">LCS</span></strong> et l'<strong>âge</strong> du patient orientent le <span class=\"kw-def\">diagnostic étiologique</span> d'une <span class=\"kw-def\">méningite</span>. Objectif central de l'item, très tombé.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tableau 1 — Analyse cytochimique du <span class=\"kw-bio\">LCS</span></h4>\n      <table >\n        <thead><tr><th>Paramètre</th><th><span class=\"kw-bio\">LCS</span> normal</th><th><span class=\"kw-def\">Méningite</span> purulente</th><th><span class=\"kw-def\">Méningite</span> à liquide clair</th></tr></thead>\n        <tbody>\n          <tr><td>Macroscopie</td><td>Clair (eau de roche)</td><td><span class=\"kw-alerte\">Trouble</span> (cytorachie &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>300</span> G</span>B/mm³)</td><td>Clair</td></tr>\n          <tr><td>Cytologie</td><td><span class=\"kw-chiffre\">&lt; 5 cellules/mm³</span> (<span class=\"kw-bio\">lymphocytes</span>)</td><td><span class=\"kw-chiffre\">&gt; 20 cellules/mm³</span>, souvent &gt; 1000, <strong>prédominance de PNN</strong></td><td><span class=\"kw-chiffre\">5-100</span> (parfois 100-1000) cellules, prédominance lymphocytaire ou formule panachée</td></tr>\n          <tr><td>Glycorachie</td><td>&gt; 2/3 de la <span class=\"kw-bio\">glycémie</span></td><td><span class=\"kw-alerte\">Hypoglycorachie ≤ 0,4 × glycémie</span> (sensibilité<span class=\"kw-chiffre\"> 80 %</span>, spécificité<span class=\"kw-chiffre\"> 98 %</span> d'une étiologie <span class=\"kw-etio\">bactérienne</span>)</td><td>Normoglycorachie si <span class=\"kw-etio\">virale</span> ; hypoglycorachie <span class=\"kw-chiffre\">≤ 0,4</span> × <span class=\"kw-bio\">glycémie</span> si <span class=\"kw-etio\">bactérienne</span></td></tr>\n          <tr><td>Protéinorachie</td><td><span class=\"kw-chiffre\">&lt; 0,40 g/L</span></td><td><span class=\"kw-alerte\">Hyperprotéinorachie &gt; 1 g/L</span></td><td>Modérée &lt;<span class=\"kw-chiffre\"> 1 g/L</span> si <span class=\"kw-etio\">virale</span> ;<span class=\"kw-chiffre\"> 1-2 g/L</span> si <span class=\"kw-etio\">bactérienne</span></td></tr>\n          <tr><td>Lactatorachie</td><td><span class=\"kw-chiffre\">&lt; 3,2 mmol/L</span></td><td><span class=\"kw-alerte\">&gt; 3,2 mmol/L</span></td><td><span class=\"kw-chiffre\">&lt; 3,2 mmol/L</span></td></tr>\n          <tr><td>Examen direct</td><td>Négatif</td><td>Positif dans <span class=\"kw-chiffre\">60-80 %</span> des cas en l'absence d'ATB</td><td>Négatif si <span class=\"kw-etio\">viral</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:18px 0 6px;font-size:14px;color:#1f2937;\">Tableau 2 — Germe prédominant selon l'âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Germe(s)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 2-3 mois</span></td><td><span class=\"kw-etio\">Streptocoque du groupe B</span> (constamment sensible à l'<span class=\"kw-ttt\">amoxicilline</span>) puis <span class=\"kw-etio\">E. coli</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">2-12 mois</span></td><td><span class=\"kw-etio\">Pneumocoque</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">1-24 ans</span></td><td><span class=\"kw-etio\">Méningocoque</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 24 ans</span></td><td><span class=\"kw-etio\">Pneumocoque</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:18px 0 6px;font-size:14px;color:#1f2937;\">Tableau 3 — <span class=\"kw-def\">Épidémiologie</span> <span class=\"kw-etio\">bactérienne</span> chez l'adulte</h4>\n      <p>3 bactéries représentent <span class=\"kw-chiffre\">90 %</span> des méningites purulentes de l'adulte.</p>\n      <table >\n        <thead><tr><th>Bactérie</th><th>Fréquence et caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Pneumocoque</span></td><td><span class=\"kw-chiffre\">50-55 %</span> ; portage VAS ; <strong>CG+ en diplocoque ou en chaînette</strong>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Méningocoque</span></td><td><span class=\"kw-chiffre\">25-30 %</span> ; portage rhinopharyngé ; <strong>CG− en diplocoque</strong> ; sérogroupes B <span class=\"kw-chiffre\">40-50 %</span> &gt; C &gt; W &gt; Y.</td></tr>\n          <tr><td><span class=\"kw-etio\">Listeria monocytogenes</span></td><td><span class=\"kw-chiffre\">5-10 %</span> ; <strong>BG+</strong> ; sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span>, <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-etio\">alcoolisme</span>, immunodépression.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Méningites à liquide clair.</strong> Formes <span class=\"kw-alerte\">hypoglycorachiques</span> : listériose, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">Cryptococcus neoformans</span>. Formes <strong>normoglycorachiques</strong> : virus (<span class=\"kw-etio\">HSV</span>, <span class=\"kw-etio\">entérovirus</span>), spirochètes (Lyme, <span class=\"kw-clinique\">syphilis</span>, leptospirose).</p>\n      <div class=\"callout callout-danger\"><strong>Piège Gram.</strong> <strong>Cocci Gram positif = <span class=\"kw-etio\">pneumocoque</span></strong> ; <strong>cocci Gram négatif = <span class=\"kw-etio\">méningocoque</span></strong> ; <strong>bacille Gram positif = <span class=\"kw-etio\">Listeria</span></strong>. Ne jamais inverser. La <span class=\"kw-bio\">glycorachie</span> s'interprète toujours en rapport à la <span class=\"kw-bio\">glycémie</span> veineuse concomitante : un seuil <span class=\"kw-chiffre\">≤ 0,4 × glycémie</span> oriente vers une étiologie <span class=\"kw-etio\">bactérienne</span> (spécificité<span class=\"kw-chiffre\"> 98 %</span>).</div>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> ~<span class=\"kw-chiffre\">30 %</span> des méningites <span class=\"kw-etio\">virales</span> (<span class=\"kw-etio\">entérovirus</span>) ont une formule <strong>purulente</strong> (à PNN) dans <span class=\"kw-clinique\">les</span> 24 premières heures.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":7},{"id":"151-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies et l'épidémiologie infectieuse des méningo-encéphalites","contenu":"<p>L'agent causal d'une <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> n'est <strong>pas identifié dans &gt;<span class=\"kw-chiffre\"> 50 %</span></strong> des cas. <span class=\"kw-etio\">HSV</span> est la 1ʳᵉ cause de <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> à liquide clair, par sa <strong>fréquence</strong> (~<span class=\"kw-chiffre\">25 %</span>) et sa <span class=\"kw-alerte\">gravité</span>.</p>\n      <p>Ce sont des infections <strong>rares mais graves</strong> : <span class=\"kw-def\">mortalité</span> de <span class=\"kw-chiffre\">2 %</span> chez l'enfant et <span class=\"kw-chiffre\">10 %</span> chez l'adulte ; <span class=\"kw-alerte\">40 % de séquelles psycho-neurologiques</span> persistent à<span class=\"kw-chiffre\"> 3 ans</span> de l'épisode.</p>\n      <div class=\"callout callout-info\"><strong>3 causes curables</strong> imposant un diagnostic et un traitement précoces : <span class=\"kw-etio\">HSV</span>, <span class=\"kw-etio\">Listeria</span> et <span class=\"kw-etio\">BK</span> (<span class=\"kw-etio\">tuberculose</span>).</div>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Agents</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Virus</span></td><td><strong><span class=\"kw-etio\">HSV</span>-1 ++</strong> ; autres herpèsvirus (HSV-2, CMV, <span class=\"kw-etio\">VZV</span>, <span class=\"kw-etio\">EBV</span>, HHV-6) ; <span class=\"kw-etio\">entérovirus</span> ; <span class=\"kw-etio\">VIH</span> (<span class=\"kw-clinique\">primo-infection</span>) ; rage ; arbovirus (West-Nile, <span class=\"kw-def\">encéphalite</span> japonaise, tick-borne encephalitis).</td></tr>\n          <tr><td><span class=\"kw-etio\">Bactéries</span></td><td><span class=\"kw-etio\">Tuberculose</span> ; <span class=\"kw-etio\">Listeria monocytogenes</span> ; <span class=\"kw-etio\">Borrelia</span> (Lyme) ; <span class=\"kw-clinique\">syphilis</span> ; leptospirose ; <span class=\"kw-etio\">Mycoplasma pneumoniae</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Parasites</span></td><td><span class=\"kw-etio\">Plasmodium falciparum</span> (<span class=\"kw-clinique\">neuropaludisme</span>) ; toxoplasmose.</td></tr>\n          <tr><td>Causes non infectieuses</td><td><span class=\"kw-etio\">Paranéoplasique</span> ; <span class=\"kw-etio\">auto-immune</span> ; post-infectieuse ; médicamenteuse.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>3 mécanismes d'<span class=\"kw-def\">encéphalite</span>.</strong> <strong>Invasif direct</strong> (infection du parenchyme, typiquement la <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> herpétique) ; <strong><span class=\"kw-etio\">post-infectieux</span> ou post-vaccinal</strong> (ADEM, processus immunologique à distance, qui répond aux <span class=\"kw-ttt\">anti-inflammatoires</span> plutôt qu'aux antiviraux) ; <strong><span class=\"kw-etio\">auto-immun</span></strong> non <span class=\"kw-etio\">infectieux</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus · 169 — <span class=\"kw-etio\">VIH</span> · 170 — <span class=\"kw-clinique\">Paludisme</span></em></p>","frequence":0},{"id":"151-9","rang":"B","rubrique":"Étiologies","titre":"Savoir citer les principales étiologies infectieuses des abcès cérébraux","contenu":"<p><span class=\"kw-clinique\">Les</span> germes responsables d'un <span class=\"kw-def\">abcès cérébral</span> dépendent de la <strong>voie de contamination</strong>.</p>\n      <table >\n        <thead><tr><th>Voie (fréquence)</th><th><span class=\"kw-clinique\">Porte d'entrée</span> et germes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Contiguïté</span> (~<span class=\"kw-chiffre\">50 %</span>)</td><td>Foyer ORL, ostéite, thrombophlébite septique ; infection souvent <strong>polymicrobienne</strong> : <span class=\"kw-etio\">streptocoques oraux</span>, <span class=\"kw-etio\">Streptococcus du groupe milleri</span>, <span class=\"kw-etio\">anaérobies</span> buccaux et pulmonaires.</td></tr>\n          <tr><td><span class=\"kw-def\">Voie hématogène</span> (~<span class=\"kw-chiffre\">30 %</span>)</td><td>Foyer dentaire, <strong><span class=\"kw-etio\">endocardite</span></strong> : <span class=\"kw-etio\">Staphylococcus aureus</span>, <span class=\"kw-etio\">Listeria</span>, <span class=\"kw-etio\">Mycobacterium tuberculosis</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Post-traumatique / post-chirurgicale</span> (~<span class=\"kw-chiffre\">10 %</span>)</td><td>Fracture ouverte du crâne, neurochirurgie : <span class=\"kw-etio\">Staphylococcus aureus</span>, entérobactéries, <span class=\"kw-etio\">Pseudomonas aeruginosa</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Porte d'entrée inconnue</span> (~<span class=\"kw-chiffre\">10 %</span>)</td><td>Aucune <span class=\"kw-clinique\">porte d'entrée</span> identifiée.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Terrain</span> immunodéprimé.</strong> Évoquer aussi la <span class=\"kw-etio\">toxoplasmose cérébrale</span>, la <span class=\"kw-etio\">nocardiose</span> et <span class=\"kw-clinique\">les</span> champignons (<span class=\"kw-etio\">Aspergillus</span>, cryptocoque, <span class=\"kw-etio\">Candida</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"151-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l'indication d'une ponction lombaire","contenu":"<p>La <span class=\"kw-def\">ponction lombaire (PL)</span> est indiquée <strong>en <span class=\"kw-alerte\">urgence</span></strong> devant toute suspicion de <span class=\"kw-def\">méningite</span> ou de <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span>. Geste réalisé sous <strong>asepsie chirurgicale</strong>, aiguille atraumatique, prélèvement de <span class=\"kw-chiffre\">2-3 mL</span> (<span class=\"kw-chiffre\">≥ 5</span> tubes), avec <span class=\"kw-bio\">glycémie veineuse concomitante</span> (indispensable pour interpréter la glycorachie).</p>\n      <table >\n        <thead><tr><th>Type de <span class=\"kw-ci\">contre-indication</span></th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ci\">Non neurologiques</span></td><td>Infection cutanée étendue au point de <span class=\"kw-ttt\">ponction</span> ; <span class=\"kw-alerte\">instabilité hémodynamique ou respiratoire</span> (a fortiori <span class=\"kw-etio\">purpura fulminans</span>) ; troubles de l'hémostase — <span class=\"kw-ttt\">anticoagulant</span> à dose efficace, coagulopathie, <span class=\"kw-chiffre\">thrombopénie &lt; 50 G/L</span>, <span class=\"kw-chiffre\">TP &lt; 50 %</span>, <span class=\"kw-chiffre\">TCA &gt; 1,5</span>, <span class=\"kw-alerte\">CIVD</span>.</td></tr>\n          <tr><td><span class=\"kw-ci\">Neurologiques</span><br>(imposent une <span class=\"kw-imagerie\">TDM cérébrale non injectée</span> préalable)</td><td>Crises convulsives persistantes ; signes de processus expansif ou d'<span class=\"kw-alerte\">HTIC</span> (déficit focal, HLH, <span class=\"kw-def\">syndrome cérébelleux</span>, crises focales récentes ou non contrôlées) ; signes d'<span class=\"kw-alerte\">engagement cérébral</span> — troubles de vigilance avec <span class=\"kw-chiffre\">Glasgow ≤ 11</span> et signes de souffrance du tronc.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Ne sont PAS des CI à la PL :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antiagrégants plaquettaires</span>, la <span class=\"kw-clinique\">confusion</span> isolée, les <span class=\"kw-clinique\">troubles de vigilance isolés</span>.</div>\n      <div class=\"callout callout-info\"><strong>Imagerie préalable.</strong> Une imagerie cérébrale avant la PL est nécessaire en cas de signes de focalisation ou d'<span class=\"kw-alerte\">HTIC</span>, de <span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">≤ 11,</span> de crises épileptiques focales ou généralisées après <span class=\"kw-chiffre\">5 ans</span>, ou de crises hémicorporelles avant <span class=\"kw-chiffre\">5 ans</span>. Complication fréquente : le <span class=\"kw-def\">syndrome post-PL</span> (<span class=\"kw-clinique\">céphalée</span> orthostatique posturale, soulagée en décubitus).</div>","frequence":3},{"id":"151-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l'indication et les objectifs des examens d'imagerie devant une suspicion de méningite, d'une encéphalite ou d'un abcès","contenu":"<p><span class=\"kw-clinique\">Les</span> indications et objectifs de l'imagerie diffèrent selon que l'on suspecte une <span class=\"kw-def\">méningite</span>, une <span class=\"kw-def\">encéphalite</span> ou un <span class=\"kw-clinique\">abcès</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Imagerie et objectifs</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Méningite</span></td><td>Imagerie cérébrale <strong>rarement nécessaire avant la PL</strong> (uniquement si <span class=\"kw-ci\">CI neurologique à la PL</span> ou suspicion d'<span class=\"kw-alerte\">engagement précoce</span> → <span class=\"kw-imagerie\">TDM non injectée</span>). Imagerie indiquée <strong>en cours d'<span class=\"kw-clinique\">évolution</span></strong> si : évolution défavorable à <span class=\"kw-chiffre\">48-72 h</span> (recherche d'<span class=\"kw-alerte\">abcès</span>, <span class=\"kw-etio\">empyème</span>, <span class=\"kw-alerte\">infarctus</span>, <span class=\"kw-alerte\">thrombophlébite</span>, <span class=\"kw-alerte\">hydrocéphalie</span>) ; nouveaux signes neurologiques ; bactérie autre que <span class=\"kw-etio\">pneumocoque</span> ou <span class=\"kw-ttt\">méningocoque</span> ; ATCD de traumatisme crânien ou de <span class=\"kw-clinique\">brèche ostéo-méningée</span> ; <span class=\"kw-def\">méningite</span> à pneumocoque compliquant une <span class=\"kw-clinique\">otite</span>, une <span class=\"kw-clinique\">sinusite</span> ou une <span class=\"kw-clinique\">mastoïdite</span>.</td></tr>\n          <tr><td><span class=\"kw-def\">Encéphalite</span></td><td><span class=\"kw-imagerie\">IRM cérébrale injectée en 1ʳᵉ intention</span> (<span class=\"kw-imagerie\">T1, T2, FLAIR, diffusion</span>, séquences vasculaires, sans et avec gadolinium) — recherche de lésions parenchymateuses, surtout <span class=\"kw-imagerie\">temporales et frontales</span> (<span class=\"kw-imagerie\">hypersignal T2/FLAIR</span>, <span class=\"kw-imagerie\">prise de contraste T1 gado</span>). La <span class=\"kw-imagerie\">TDM</span> est en 2ⁿᵈ intention.</td></tr>\n          <tr><td><span class=\"kw-def\">Abcès</span></td><td><span class=\"kw-imagerie\">IRM cérébrale injectée</span> (référence) ou à défaut <span class=\"kw-imagerie\">TDM injectée</span> — <span class=\"kw-imagerie\">lésion arrondie, bien circonscrite</span>, avec <span class=\"kw-imagerie\">prise de contraste annulaire en cocarde</span> ; la séquence de <span class=\"kw-imagerie\">diffusion</span> montre une <span class=\"kw-imagerie\">restriction au centre nécrotique (ADC bas)</span>, ce qui distingue l'<span class=\"kw-clinique\">abcès</span> d'une <span class=\"kw-clinique\">nécrose</span> <span class=\"kw-etio\">tumorale</span> (<span class=\"kw-imagerie\">ADC haut</span>).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une imagerie normale (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>) <span class=\"kw-alerte\">n'élimine jamais</span> une <span class=\"kw-def\">encéphalite</span> ni une <span class=\"kw-def\">méningite</span> — le diagnostic reste <strong>clinique et <span class=\"kw-ttt\">biologique</span></strong>.</div>","frequence":2},{"id":"151-12","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques de gravité d'une méningite","contenu":"<p>Tout <span class=\"kw-alerte\">signe de gravité</span> justifie une <span class=\"kw-alerte\">hospitalisation en réanimation ou en soins intensifs</span>.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th><span class=\"kw-alerte\">Signes de gravité</span></th></tr></thead>\n        <tbody>\n          <tr><td>Cutané</td><td><span class=\"kw-alerte\">Purpura extensif</span> — à rechercher systématiquement sur le patient <span class=\"kw-clinique\">entièrement déshabillé</span>.</td></tr>\n          <tr><td>Hémodynamique / respiratoire</td><td><span class=\"kw-alerte\">Instabilité hémodynamique</span> (<span class=\"kw-etio\">sepsis</span>, <span class=\"kw-etio\">choc septique</span>) ; <span class=\"kw-alerte\">détresse respiratoire</span> ; <span class=\"kw-alerte\">défaillance d'un autre organe</span>.</td></tr>\n          <tr><td>Neurologique</td><td><span class=\"kw-chiffre\">Glasgow ≤ 11</span> ; signes de <span class=\"kw-clinique\">focalisation</span> ; signes de souffrance du <span class=\"kw-alerte\">tronc cérébral</span> (<span class=\"kw-alerte\">engagement</span>) ; <span class=\"kw-alerte\">état de mal convulsif</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Un <span class=\"kw-alerte\">purpura fébrile extensif</span> est un <span class=\"kw-etio\">purpura fulminans</span> jusqu'à preuve du contraire — <span class=\"kw-ttt\">antibiothérapie immédiate</span> avant tout transfert.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-etio\">Sepsis</span> et <span class=\"kw-etio\">choc septique</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"151-13","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier un purpura fulminans (voir item 332)","contenu":"<p>Le <span class=\"kw-etio\">purpura fulminans</span> est un <span class=\"kw-clinique\">purpura vasculaire</span>, <strong>ne s'effaçant pas à la vitropression</strong>, dont <span class=\"kw-clinique\">les</span> éléments s'étendent rapidement en <strong>taille et en nombre</strong> (en quelques minutes ou heures, débutant volontiers aux <span class=\"kw-clinique\">membres inférieurs</span>, aspect <span class=\"kw-clinique\">en carte de géographie</span>). Il doit comporter <strong>soit <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-clinique\">élément nécrotique</span>, soit ≥ 1 <span class=\"kw-clinique\">élément ecchymotique</span> de <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">≥ 3 mm</span></strong>.</p>\n      <div class=\"callout callout-danger\"><strong>Dogme.</strong> <span class=\"kw-alerte\">Tout purpura fébrile est un purpura fulminans jusqu'à preuve du contraire</span> — il évolue rapidement vers un <span class=\"kw-alerte\">choc septique gravissime</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">20-40 %</span>) ; <span class=\"kw-clinique\">les</span> survivants subissent fréquemment des <span class=\"kw-alerte\">amputations d'extrémités de membres</span>.</div>\n      <p><strong>Germes :</strong> <span class=\"kw-etio\">méningocoque</span> le plus souvent ; <span class=\"kw-etio\">pneumocoque</span> plus rare (surtout <span class=\"kw-clinique\">splénectomisé</span>, <span class=\"kw-clinique\">sujet âgé</span>) ; <span class=\"kw-etio\">streptocoque</span>, <span class=\"kw-etio\">Haemophilus</span> et <span class=\"kw-etio\">staphylocoque</span> exceptionnels.</p>\n      <div class=\"callout callout-warn\"><strong>Pièges diagnostiques.</strong> <span class=\"kw-clinique\">Les</span> lésions sont <strong>violacées ou pâles</strong> (pas rouge vif) et peuvent être prises à tort pour une <span class=\"kw-clinique\">cyanose des extrémités</span> ou des <span class=\"kw-clinique\">marbrures</span> — la clé est qu'elles <strong>ne s'effacent pas à la pression</strong>. Chez l'enfant, le tableau est parfois fruste, avec peu de <span class=\"kw-clinique\">fièvre</span> voire une <span class=\"kw-alerte\">hypothermie</span>.</div>\n      <p>Le <span class=\"kw-clinique\">purpura</span> fulminans <strong>n'est pas une infection neuroméningée</strong> : l'atteinte méningée est souvent au 2ⁿᵈ plan.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 158 — <span class=\"kw-etio\">Sepsis</span> et <span class=\"kw-etio\">choc septique</span></em></p>","frequence":0},{"id":"151-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge thérapeutique d'un purpura fulminans avec posologie des C3G par voie intraveineuse","contenu":"<p><strong>Prise en charge pré-hospitalière.</strong></p>\n      <ul>\n        <li>Appel systématique au <strong><span class=\"kw-alerte\">SAMU</span> (15)</strong>.</li>\n        <li>Si <span class=\"kw-alerte\">état de choc</span> : pose d'une VVP et <span class=\"kw-ttt\">remplissage vasculaire</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Antibiothérapie</span> immédiate IV</strong> (ou IM à défaut), <strong>avant tout prélèvement</strong> (voir doses ci-dessous).</li>\n      </ul>\n      <table >\n        <thead><tr><th>Antibiotique IV</th><th>Posologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Ceftriaxone</span> (sans <span class=\"kw-ttt\">lidocaïne</span>), de préférence</td><td><span class=\"kw-chiffre\">1 à 2 g</span> chez l'adulte ; <span class=\"kw-chiffre\">50-100 mg/kg</span> chez l'enfant.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Céfotaxime</span> (sans <span class=\"kw-ttt\">lidocaïne</span>), à défaut</td><td><span class=\"kw-chiffre\">1 à 2 g</span> chez l'adulte ; <span class=\"kw-chiffre\">50 mg/kg</span> chez l'enfant.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Amoxicilline</span>, à défaut</td><td><span class=\"kw-chiffre\">1 g</span> chez l'adulte.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Prise en charge hospitalière.</strong> Transfert en <strong><span class=\"kw-alerte\">réanimation</span></strong> ; poursuite de la <span class=\"kw-ttt\">C3G</span> à dose méningée ; <strong>prélèvements microbiologiques après mise en route de l'ATB</strong> (<span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-bio\">biopsie cutanée</span> des lésions purpuriques) ; bilan sanguin complet (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">bilan hépatique</span> et rénal, <span class=\"kw-bio\">coagulation</span>, <span class=\"kw-bio\">gazométrie</span>).</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> La <span class=\"kw-ci\">ponction lombaire est contre-indiquée</span> (instabilité hémodynamique, troubles de l'hémostase par <span class=\"kw-alerte\">CIVD</span>). Le <span class=\"kw-clinique\">purpura</span> fulminans n'étant pas une <span class=\"kw-def\">méningite</span> purulente, la <span class=\"kw-ci\">dexaméthasone n'est pas indiquée</span>.</div>\n      <p><strong>Mesures associées :</strong> précautions <span class=\"kw-ttt\">gouttelettes</span> (levées <span class=\"kw-chiffre\">24 h</span> après ATB efficace) ; <strong><span class=\"kw-def\">signalement</span> et déclaration à l'ARS</strong> ; <span class=\"kw-ttt\">antibioprophylaxie</span> et <span class=\"kw-ttt\">vaccination</span> des sujets contacts.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 158 — <span class=\"kw-etio\">Sepsis</span> et <span class=\"kw-etio\">choc septique</span></em></p>","frequence":0},{"id":"151-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge immédiate en cas de suspicion de méningite","contenu":"<p>Devant une <strong>suspicion de <span class=\"kw-def\">méningite</span></strong>, la prise en charge immédiate combine <span class=\"kw-def\">isolement</span>, recherche de gravité et bilan microbiologique sans retarder le traitement.</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Précautions gouttelettes</span> (<span class=\"kw-ttt\">masque chirurgical</span>) tant que la <span class=\"kw-def\">méningite</span> à <span class=\"kw-etio\">méningocoque</span> n'est pas écartée, ou pendant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 premières heures</span> d'ATB.</li>\n        <li>Rechercher <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span> → <span class=\"kw-alerte\">orientation en réanimation</span>.</li>\n        <li><strong>Paraclinique immédiat</strong> : 2 <span class=\"kw-bio\">hémocultures</span> et <span class=\"kw-bio\">ponction lombaire</span>. Imagerie cérébrale rarement nécessaire avant la PL.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Quand débuter l'<span class=\"kw-ttt\">antibiothérapie</span> ?</h4>\n      <table >\n        <thead><tr><th>Moment</th><th>Situation</th></tr></thead>\n        <tbody>\n          <tr><td>Avant <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, sans PL</td><td>Suspicion de <span class=\"kw-alerte\">purpura fulminans en préhospitalier</span>.</td></tr>\n          <tr><td>Après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, sans PL</td><td><span class=\"kw-etio\">Purpura fulminans</span> pris en charge à l'hôpital.</td></tr>\n          <tr><td>Après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, avant la PL</td><td><span class=\"kw-ci\">Contre-indication</span> à la PL, ou hôpital situé à <span class=\"kw-chiffre\">&gt; 90 min</span>.</td></tr>\n          <tr><td>Après la PL, sans attendre <span class=\"kw-clinique\">les</span> résultats</td><td><span class=\"kw-bio\">LCS</span> <span class=\"kw-bio\">macroscopiquement trouble</span>, ou très forte suspicion de <span class=\"kw-def\">méningite</span> <span class=\"kw-etio\">bactérienne</span>.</td></tr>\n          <tr><td>En <span class=\"kw-alerte\">urgence</span> (&lt;<span class=\"kw-chiffre\"> 1 h</span>) après <span class=\"kw-clinique\">les</span> résultats</td><td><span class=\"kw-bio\">Examen direct positif</span>, <span class=\"kw-bio\">antigène pneumocoque positif</span>, ou faisceau d'arguments biologiques en faveur d'une <span class=\"kw-def\">méningite</span> <span class=\"kw-etio\">bactérienne</span>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Traitement symptomatique :</strong> <span class=\"kw-ttt\">antalgique</span>, <span class=\"kw-ttt\">antipyrétique</span>, correction des troubles hémodynamiques, <span class=\"kw-ttt\">anti-épileptique</span> si crise.</p>\n      <p><strong>Bilan :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">dépistage VIH systématique</span> (après information du patient).</p>","frequence":5},{"id":"151-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et les modalités de l'antibiothérapie probabiliste devant une méningite présumée bactérienne","contenu":"<p>L'<strong><span class=\"kw-ttt\">antibiothérapie</span> probabiliste</strong> d'une <span class=\"kw-def\">méningite</span> présumée <span class=\"kw-etio\">bactérienne</span> est <strong>guidée par l'examen direct</strong> du <span class=\"kw-bio\">LCS</span>.</p>\n      <table >\n        <thead><tr><th>Examen direct du <span class=\"kw-bio\">LCS</span></th><th><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Diplocoque Gram +</strong> (<span class=\"kw-etio\">pneumocoque</span>)</td><td><span class=\"kw-ttt\">C3G</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) IV + <span class=\"kw-ttt\">dexaméthasone</span>.</td></tr>\n          <tr><td><strong>Diplocoque Gram −</strong> (<span class=\"kw-etio\">méningocoque</span>)</td><td><span class=\"kw-ttt\">C3G</span> IV + <span class=\"kw-ttt\">dexaméthasone</span>.</td></tr>\n          <tr><td><strong>Bacille Gram +</strong> (<span class=\"kw-etio\">Listeria</span>)</td><td><span class=\"kw-ttt\">Amoxicilline + gentamicine</span> — <span class=\"kw-ci\">pas de dexaméthasone</span>.</td></tr>\n          <tr><td><span class=\"kw-bio\">LCS</span> purulent, examen direct négatif, <strong>sans</strong> argument pour <span class=\"kw-etio\">Listeria</span></td><td><span class=\"kw-ttt\">C3G + dexaméthasone</span> (+ <span class=\"kw-ttt\">gentamicine</span> si nourrisson &lt;<span class=\"kw-chiffre\"> 3 mois</span>).</td></tr>\n          <tr><td><span class=\"kw-bio\">LCS</span> purulent, examen direct négatif, <strong>avec</strong> argument pour <span class=\"kw-etio\">Listeria</span> (<span class=\"kw-def\">terrain</span>, installation progressive, atteinte rhombencéphalique) ou <span class=\"kw-bio\">LCS</span> panaché hypoglycorachique</td><td><span class=\"kw-ttt\">C3G + amoxicilline + gentamicine</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-ttt\">Dexaméthasone</span> (<span class=\"kw-ttt\">corticothérapie</span>).</strong> Réduit de ~<span class=\"kw-chiffre\">50 %</span> <span class=\"kw-clinique\">les</span> décès et les séquelles dans les méningites à <span class=\"kw-etio\">pneumocoque</span>. Indications : <span class=\"kw-def\">méningite</span> à <span class=\"kw-etio\">pneumocoque</span> ou <span class=\"kw-ttt\">méningocoque</span> (adulte), à pneumocoque ou Haemophilus (enfant), ou <span class=\"kw-def\">méningite</span> <span class=\"kw-etio\">bactérienne</span> présumée. Voie <strong>IV</strong>, débutée <strong>avant la 1ʳᵉ injection d'ATB</strong> (ou au plus tard dans les <span class=\"kw-chiffre\">12 h</span>), durée <span class=\"kw-chiffre\">4 jours</span>.</div>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span>.</strong> La <span class=\"kw-ci\">dexaméthasone est contre-indiquée</span> en cas de forte suspicion de <span class=\"kw-etio\">neurolistériose</span> et chez <span class=\"kw-clinique\">les</span> patients <strong>immunodéprimés</strong>.</div>","frequence":5},{"id":"151-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge thérapeutique des méningites infectieuses non purulentes","contenu":"<p>La prise en charge des <span class=\"kw-def\">méningites infectieuses non purulentes</span> (à liquide clair) dépend de l'étiologie.</p>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Méningites virales</span><br>(<span class=\"kw-bio\">LCS</span> lymphocytaire normoglycorachique)</td><td><span class=\"kw-ttt\">Traitement symptomatique</span> dans la plupart des cas (<span class=\"kw-etio\">entérovirus</span> — pas de traitement spécifique). <strong>Toujours rechercher des signes d'<span class=\"kw-def\">encéphalite</span></strong> : leur présence impose un traitement par <span class=\"kw-ttt\">aciclovir IV</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Primo-infection VIH</span></td><td><span class=\"kw-ttt\">Traitement antirétroviral</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Listeria</span><br>(<span class=\"kw-bio\">LCS</span> lymphocytaire ou panaché, hypoglycorachique)</td><td><span class=\"kw-ttt\">Amoxicilline 21 jours + gentamicine 5 jours</span> ; <span class=\"kw-ci\">pas de dexaméthasone</span> ; <span class=\"kw-ttt\">cotrimoxazole</span> si <span class=\"kw-ci\">allergie</span> aux β-lactamines.</td></tr>\n          <tr><td><span class=\"kw-etio\">Tuberculose</span></td><td><span class=\"kw-ttt\">Quadrithérapie 2 mois</span> (INH + RMP + EMB + PZA) puis <span class=\"kw-ttt\">bithérapie 7-10 mois</span> (INH + RMP) + <span class=\"kw-ttt\">corticothérapie</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Lyme</span> / <span class=\"kw-etio\">Syphilis</span></td><td>Lyme : <span class=\"kw-ttt\">ceftriaxone IV</span><span class=\"kw-chiffre\"> 15-21 jours</span>. <span class=\"kw-clinique\">Syphilis</span> : <span class=\"kw-ttt\">pénicilline G IV</span><span class=\"kw-chiffre\"> 2-3 semaines</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant une <span class=\"kw-def\">méningite</span> lymphocytaire fébrile, toujours évoquer en parallèle une <span class=\"kw-etio\">méningo-encéphalite herpétique</span> (signes encéphalitiques) et une <span class=\"kw-etio\">listériose</span> — d'où l'association probabiliste <span class=\"kw-ttt\">aciclovir + amoxicilline</span> tant que le diagnostic n'est pas tranché.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"151-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir immédiate en cas de suspicion de méningo-encéphalite herpétique","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> La <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> herpétique est une <span class=\"kw-alerte\">urgence diagnostique ET thérapeutique</span> — la <strong>précocité du traitement</strong> est un facteur majeur de bon <span class=\"kw-def\">pronostic</span>.</div>\n      <p>L'<span class=\"kw-ttt\">aciclovir IV</span> est débuté <strong>le plus rapidement possible</strong>, <strong>sans attendre</strong> <span class=\"kw-clinique\">les</span> résultats de la <span class=\"kw-bio\">PCR HSV dans le LCS</span> ni de l'<span class=\"kw-imagerie\">IRM</span>.</p>\n      <p><strong>Association probabiliste</strong> devant un <span class=\"kw-bio\">LCS</span> lymphocytaire ou panaché fébrile : <span class=\"kw-ttt\">aciclovir</span> (vise <span class=\"kw-etio\">HSV-1</span>) + <span class=\"kw-ttt\">amoxicilline</span> (vise <span class=\"kw-etio\">Listeria</span>). En cas de suspicion de <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> avec <span class=\"kw-ci\">CI à la PL</span> : <span class=\"kw-ttt\">C3G + aciclovir + amoxicilline</span>.</p>\n      <p><strong>Modalités de l'<span class=\"kw-ttt\">aciclovir</span> :</strong> IV toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">8 h</span>, <span class=\"kw-chiffre\">15-21 jours</span> ; <strong>perfusion lente et bonne hydratation</strong> car risque d'<span class=\"kw-alerte\">insuffisance rénale aiguë par tubulopathie obstructive</span> (cristaux d'<span class=\"kw-ttt\">aciclovir</span> intra-tubulaires), dose-dépendant.</p>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Réévaluation</span>.</strong> 2ᵉ <span class=\"kw-bio\">PCR HSV</span> sur <span class=\"kw-bio\">LCS</span> entre <span class=\"kw-chiffre\">J4 et J10</span> ; le traitement peut être interrompu si <strong>2 <span class=\"kw-bio\">PCR</span> <span class=\"kw-etio\">HSV</span> négatives</strong> avec un tableau peu évocateur (le traitement ne négative pas la <span class=\"kw-bio\">PCR</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p>","frequence":2},{"id":"151-19","rang":"A","rubrique":"Suivi et/ou Pronostic","titre":"Connaître les mesures générales à prendre pour la personne atteinte et son entourage en cas d'infection invasive à méningocoque","contenu":"<p>Devant une <span class=\"kw-etio\">infection invasive à méningocoque</span> (<span class=\"kw-def\">méningite</span>, <span class=\"kw-clinique\">bactériémie</span>, <span class=\"kw-clinique\">purpura</span> fulminans), des mesures concernent à la fois le patient et son entourage.</p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Précautions gouttelettes</span></td><td>Masque chirurgical ; <strong>levées <span class=\"kw-chiffre\">24 h</span> après le début</strong> d'une <span class=\"kw-ttt\">antibiothérapie</span> efficace.</td></tr>\n          <tr><td>Éviction</td><td>Éviction des collectivités jusqu'à guérison clinique.</td></tr>\n          <tr><td>Déclaration</td><td><strong><span class=\"kw-def\">Signalement</span> à l'ARS sans délai</strong> (nominatif) puis <strong>notification à l'<span class=\"kw-def\">ARS</span></strong> (formulaire spécifique, anonyme).</td></tr>\n          <tr><td>Sujets contacts</td><td><span class=\"kw-def\">Contact</span> avec <span class=\"kw-clinique\">les</span> sécrétions oropharyngées : direct (face à face), proche (<span class=\"kw-chiffre\">&lt; 1 m</span>), prolongé (<span class=\"kw-chiffre\">&gt; 1 h</span>), durant les <span class=\"kw-chiffre\">10 jours précédents</span> ; flirt ; soignant ayant fait un bouche-à-bouche, une <span class=\"kw-ttt\">intubation</span> ou une aspiration sans masque ; au minimum tous les membres vivant <strong>sous le même toit</strong>.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibioprophylaxie</span> des contacts</td><td>Urgente, dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24-48 h</span> (au plus tard 10 j) : <span class=\"kw-ttt\">rifampicine per os pendant 2 jours</span> (référence). Si CI ou résistance : <span class=\"kw-ttt\">ceftriaxone</span> ou <span class=\"kw-ttt\">ciprofloxacine</span> en dose unique.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Vaccination</span> des contacts<br>(&lt;<span class=\"kw-chiffre\"> 10 jours</span>)</td><td>Sérogroupe <strong>C</strong> → <span class=\"kw-ttt\">vaccin conjugué C</span> ; sérogroupes <strong>A/Y/W</strong> → <span class=\"kw-ttt\">vaccin conjugué tétravalent ACYW</span> ; sérogroupe <strong>B</strong> non recommandé autour des cas sporadiques (décision des autorités sanitaires).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ttt\">Rifampicine</span>.</strong> Informer de la <span class=\"kw-clinique\">coloration orange des urines et des larmes</span> (porteurs de lentilles), de la <span class=\"kw-alerte\">baisse d'efficacité des contraceptifs oraux</span>, et supplémenter le nouveau-né en <span class=\"kw-ttt\">vitamine K</span> si la mère est traitée. L'<span class=\"kw-ttt\">antibioprophylaxie</span> est <strong>inutile</strong> si le contage a eu lieu après le début de l'ATB du cas index par C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":2},{"id":"151-20","rang":"A","rubrique":"Définition","titre":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez le nouveau né et le nourrisson","contenu":"<p>Comme chez l'adulte, la <span class=\"kw-def\">méningite</span> du nouveau-né et du nourrisson est une <span class=\"kw-def\">réaction inflammatoire de l'espace méningé</span>, le plus souvent d'origine <span class=\"kw-etio\">infectieuse</span>. L'<strong><span class=\"kw-def\">incidence</span> des méningites bactériennes est beaucoup plus élevée chez l'enfant que chez l'adulte</strong>.</p>\n      <table >\n        <thead><tr><th>Âge</th><th>Germes</th></tr></thead>\n        <tbody>\n          <tr><td>Nourrisson <span class=\"kw-chiffre\">&lt; 2-3 mois</span></td><td><span class=\"kw-etio\">Streptocoque du groupe B</span> (1ᵉʳ germe avant <span class=\"kw-chiffre\">2 mois</span>, constamment sensible à l'<span class=\"kw-ttt\">amoxicilline</span>) puis <span class=\"kw-etio\">E. coli</span> (2ᵉ germe) ; <span class=\"kw-etio\">Listeria monocytogenes</span> représente ~<span class=\"kw-chiffre\">1 %</span> des méningites bactériennes du nouveau-né (3ᵉ cause après <span class=\"kw-etio\">E. coli K1</span> et <span class=\"kw-etio\">SGB</span>).</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2 à 12 mois</span></td><td>Prédominance du <span class=\"kw-etio\">pneumocoque</span>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Particularités.</strong> Le <span class=\"kw-clinique\">syndrome méningé est souvent trompeur ou fruste</span> chez le nourrisson — le tableau peut se limiter à une <span class=\"kw-clinique\">obnubilation</span>, une <span class=\"kw-clinique\">asthénie</span> ou des <span class=\"kw-clinique\">troubles du comportement</span>. La <span class=\"kw-def\">méningo-<span class=\"kw-def\">encéphalite</span></span> à <span class=\"kw-etio\">HSV-2</span> survient surtout en <strong>période néonatale</strong> (contamination à l'accouchement) et <span class=\"kw-chiffre\">entre 6 mois et 2 ans</span>, volontiers sous la forme d'un <span class=\"kw-alerte\">sepsis néonatal grave</span> multiviscéral.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources du dossier <code>151-méningites-encéphalites/</code> ne contiennent pas de section dédiée détaillée à la définition pédiatrique néonatale (renvoi Notion « <span class=\"kw-def\">Méningite</span> du nourrisson » non disponible). Kevin enrichira ce paragraphe depuis le Pilly ou le Collège de pédiatrie si nécessaire.</div>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Dogme :</strong> tout <span class=\"kw-alerte\">purpura fébrile</span> est un <span class=\"kw-etio\">purpura fulminans</span> jusqu’à preuve du contraire → <span class=\"kw-ttt\">antibiothérapie</span> IV immédiate AVANT tout prélèvement et tout transfert.<br><strong><span class=\"kw-clinique\">Méningite</span> / méningo-encéphalite :</strong> <span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique — <span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-bio\">ponction lombaire</span> sans délai, l’imagerie ne doit pas retarder l’ATB.</p><p><strong><span class=\"kw-clinique\">Purpura</span> fulminans</strong></p><ul><li>au domicile : appel <span class=\"kw-ttt\">SAMU (15)</span> + <span class=\"kw-ttt\">antibiothérapie</span> IV/IM avant tout</li><li><span class=\"kw-ttt\">ceftriaxone</span> <span class=\"kw-chiffre\">1 à 2 g</span> adulte / <span class=\"kw-chiffre\">50-100 mg/kg</span> enfant — sans attendre la <span class=\"kw-bio\">PL</span> (<span class=\"kw-ci\">contre-indiquée</span>)</li></ul><p><strong>Quand débuter l’<span class=\"kw-ttt\">antibiothérapie</span> ?</strong></p><ul><li><strong>avant</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, sans <span class=\"kw-bio\">PL</span> : <span class=\"kw-alerte\">purpura fulminans</span> en préhospitalier</li><li><strong>après</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, sans <span class=\"kw-bio\">PL</span> : <span class=\"kw-alerte\">purpura fulminans</span> pris en charge à l’hôpital</li><li><strong>après</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> et <strong>avant</strong> la <span class=\"kw-bio\">PL</span> : <span class=\"kw-ci\">CI à la PL</span> ou hôpital à <span class=\"kw-chiffre\">&gt; 90 min</span></li><li><strong>après</strong> la <span class=\"kw-bio\">PL</span>, sans attendre <span class=\"kw-clinique\">les</span> résultats : <span class=\"kw-bio\">LCS trouble</span> ou très forte suspicion <span class=\"kw-etio\">bactérienne</span></li><li>en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 1 h</span> après <span class=\"kw-clinique\">les</span> résultats : <span class=\"kw-bio\">examen direct</span> ou <span class=\"kw-bio\">antigène pneumocoque</span> positif</li></ul><p><strong>Délais associés</strong></p><ul><li><span class=\"kw-ttt\">dexaméthasone</span> : avant la 1<sup>re</sup> injection d’ATB ou au plus tard dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">12 h</span></li><li><span class=\"kw-clinique\">méningo-encéphalite</span> : <span class=\"kw-ttt\">aciclovir</span> IV sans attendre la <span class=\"kw-bio\">PCR HSV</span> ni l’<span class=\"kw-imagerie\">IRM</span></li><li><span class=\"kw-ttt\">antibioprophylaxie</span> des contacts : dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24-48 h</span> (au plus tard <span class=\"kw-chiffre\">10 j</span>)</li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Réanimation</span> / soins intensifs</strong> dès qu’il existe <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-alerte\">signe de gravité</span> ; <span class=\"kw-alerte\">hospitalisation</span> initiale en réanimation ou SI recommandée pour toute <span class=\"kw-def\">méningite purulente</span>.<br><strong>Précautions <span class=\"kw-def\">gouttelettes</span></strong> (<span class=\"kw-ttt\">masque chirurgical</span>) tant que la <span class=\"kw-def\">méningite</span> à <span class=\"kw-etio\">méningocoque</span> n’est pas écartée, ou pendant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 premières heures</span> d’ATB efficace.</p><p><strong>Orientation selon le tableau</strong></p><ul><li><span class=\"kw-alerte\">purpura fulminans</span> → <span class=\"kw-ttt\">remplissage vasculaire</span> si <span class=\"kw-alerte\">choc</span> + transfert en <strong><span class=\"kw-alerte\">réanimation</span></strong></li><li><span class=\"kw-def\">méningite purulente</span> → <span class=\"kw-alerte\">réanimation</span> ou soins intensifs</li><li><span class=\"kw-def\">méningo-encéphalite</span> → <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">aciclovir</span> IV, <span class=\"kw-def\">surveillance</span> neuropsychologique prolongée</li><li><span class=\"kw-def\">abcès cérébral</span> → prise en charge <strong>médico-chirurgicale</strong> en <span class=\"kw-alerte\">urgence</span> (aspiration au cours de la <span class=\"kw-ttt\">ponction-biopsie neurochirurgicale</span>)</li></ul>","redflags":"<p>Tout <span class=\"kw-alerte\">signe de gravité</span> justifie une <span class=\"kw-alerte\">hospitalisation en réanimation ou en soins intensifs</span>. Recherche du <span class=\"kw-alerte\">purpura</span> sur un patient <strong>entièrement déshabillé</strong>.</p><ul><li><span class=\"kw-alerte\">Purpura extensif</span> / <span class=\"kw-alerte\">purpura fulminans</span></li><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> (<span class=\"kw-etio\">sepsis</span>, <span class=\"kw-alerte\">choc septique</span>)</li><li><span class=\"kw-alerte\">Détresse respiratoire</span> ou <span class=\"kw-alerte\">défaillance d’un autre organe</span></li><li><span class=\"kw-alerte\">Glasgow ≤ 11</span> (<span class=\"kw-chiffre\">≤ 13</span> selon le seuil d’orientation en <span class=\"kw-alerte\">réanimation</span>)</li><li>Signes de <span class=\"kw-alerte\">focalisation</span> neurologique</li><li>Signes de souffrance du <span class=\"kw-alerte\">tronc cérébral</span> (<span class=\"kw-alerte\">engagement</span>)</li><li><span class=\"kw-alerte\">État de mal convulsif</span> ou <span class=\"kw-chiffre\">&gt; 1</span> crise convulsive</li><li><span class=\"kw-alerte\">Troubles du comportement</span> incompatibles avec le secteur conventionnel</li></ul>","principes":"<p><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste guidée par l’<span class=\"kw-bio\">examen direct</span> du <span class=\"kw-bio\">LCS</span></strong> ; <span class=\"kw-ttt\">dexaméthasone</span> IV associée aux <span class=\"kw-def\">méningites bactériennes</span> (sauf <span class=\"kw-etio\">listériose</span> et immunodéprimé).</p><ul><li><strong>Diplocoque Gram +</strong> (<span class=\"kw-etio\">pneumocoque</span>) : <span class=\"kw-ttt\">C3G</span> (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) IV + <span class=\"kw-ttt\">dexaméthasone</span> — durée <span class=\"kw-chiffre\">10-14 j</span></li><li><strong>Diplocoque Gram −</strong> (<span class=\"kw-etio\">méningocoque</span>) : <span class=\"kw-ttt\">C3G</span> IV + <span class=\"kw-ttt\">dexaméthasone</span> — durée <span class=\"kw-chiffre\">4-7 j</span></li><li><strong>Bacille Gram +</strong> (<span class=\"kw-etio\">Listeria</span>) : <span class=\"kw-ttt\">amoxicilline</span> (<span class=\"kw-chiffre\">21 j</span>) + <span class=\"kw-ttt\">gentamicine</span> (<span class=\"kw-chiffre\">5 j</span>) — <span class=\"kw-ci\">pas de dexaméthasone</span></li><li><strong>Examen direct négatif, <span class=\"kw-bio\">LCS</span> purulent</strong> : <span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">dexaméthasone</span> (+ <span class=\"kw-ttt\">gentamicine</span> si nourrisson <span class=\"kw-chiffre\">&lt; 3 mois</span>) ; ajouter <span class=\"kw-ttt\">amoxicilline + gentamicine</span> si arguments pour <span class=\"kw-etio\">Listeria</span></li><li><strong><span class=\"kw-bio\">LCS</span> lymphocytaire / panaché fébrile</strong> : <span class=\"kw-ttt\">aciclovir</span> (vise <span class=\"kw-etio\">HSV-1</span>) + <span class=\"kw-ttt\">amoxicilline</span> (vise <span class=\"kw-etio\">Listeria</span>) ; si <span class=\"kw-ci\">CI à la PL</span> : <span class=\"kw-ttt\">C3G + aciclovir + amoxicilline</span></li><li><span class=\"kw-ttt\">Dexaméthasone</span> : <span class=\"kw-chiffre\">10 mg</span> adulte / <span class=\"kw-chiffre\">0,15 mg/kg</span> enfant toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 h</span>, IV, <span class=\"kw-chiffre\">4 jours</span> (réduit de <span class=\"kw-chiffre\">~50 %</span> décès et séquelles du <span class=\"kw-etio\">pneumocoque</span>)</li><li><span class=\"kw-ttt\">Aciclovir</span> : IV, <span class=\"kw-chiffre\">15-21 j</span>, en <strong>perfusion lente + hydratation</strong> (risque d’<span class=\"kw-alerte\">insuffisance rénale</span>)</li><li><span class=\"kw-ttt\">Traitement symptomatique</span> : <span class=\"kw-ttt\">antalgique</span>, <span class=\"kw-ttt\">antipyrétique</span>, <span class=\"kw-ttt\">anti-épileptique</span> si crise, correction des troubles hémodynamiques</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> rapprochée <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 premières heures</span> :</strong> pouls, PA, température, vigilance, FR, revêtement cutané, examen neurologique ; efficacité jugée sur la clinique (<span class=\"kw-clinique\">fièvre</span>, signes neurologiques).</p><p><strong>Imagerie cérébrale (non systématique)</strong></p><ul><li><span class=\"kw-clinique\">évolution</span> défavorable à <span class=\"kw-chiffre\">48-72 h</span> → recherche d’<span class=\"kw-alerte\">abcès</span>, <span class=\"kw-etio\">empyème</span>, <span class=\"kw-alerte\">infarctus</span>, <span class=\"kw-alerte\">thrombophlébite</span>, <span class=\"kw-alerte\">hydrocéphalie</span></li><li>nouveaux signes neurologiques, bactérie autre que <span class=\"kw-etio\">pneumocoque</span>/<span class=\"kw-ttt\">méningocoque</span>, ATCD de traumatisme crânien ou <span class=\"kw-clinique\">brèche ostéo-méningée</span></li></ul><p><strong>PL de contrôle (<span class=\"kw-chiffre\">48-72 h</span>)</strong></p><ul><li><span class=\"kw-def\">méningite</span> à <span class=\"kw-etio\">pneumocoque</span> avec <span class=\"kw-chiffre\">CMI C3G &gt; 0,5 mg/L</span></li><li><span class=\"kw-clinique\">évolution</span> clinique défavorable (impose aussi une imagerie cérébrale)</li><li>bactéries inhabituelles (hors <span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-ttt\">méningocoque</span>, Haemophilus, <span class=\"kw-etio\">Listeria</span>)</li></ul><p><strong><span class=\"kw-etio\">Méningocoque</span> — entourage</strong></p><ul><li><span class=\"kw-ttt\">déclaration obligatoire</span> : <span class=\"kw-def\">signalement</span> à l’ARS sans délai (nominatif) + notification (anonyme)</li><li><span class=\"kw-ttt\">antibioprophylaxie</span> des contacts : <span class=\"kw-ttt\">rifampicine</span> per os <span class=\"kw-chiffre\">2 jours</span> (à défaut <span class=\"kw-ttt\">ceftriaxone</span> ou <span class=\"kw-ttt\">ciprofloxacine</span> dose unique)</li><li><span class=\"kw-ttt\">vaccination</span> des contacts (<span class=\"kw-chiffre\">&lt; 10 jours</span>) selon le sérogroupe ; éviction des collectivités jusqu’à guérison</li></ul><p><strong>Cas particuliers</strong></p><ul><li><span class=\"kw-def\">méningite virale</span> : sortie dès l’étiologie <span class=\"kw-etio\">bactérienne</span> écartée, pas de <span class=\"kw-def\">suivi</span> particulier</li><li><span class=\"kw-def\">méningo-encéphalite</span> : <span class=\"kw-def\">surveillance</span> neuropsychologique prolongée (séquelles)</li><li><span class=\"kw-etio\">pneumocoque</span> : recherche d’une <span class=\"kw-clinique\">brèche ostéo-méningée</span> + <span class=\"kw-def\">suivi</span> <span class=\"kw-bio\">audiométrique</span> chez l’enfant</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/meningites-meningoencephalites-abces-cerebral-chez-ladulte-et-lenfant","label":"Collège CEN — Méningites/méningo-encéphalites/abcès"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-151-version2024-copyright.pdf","label":"Collège Pilly — Méningites (item 151, PDF 2024)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/47.%20Purpura%20fulminans.pdf","label":"Collège CE-MIR — Purpura fulminans (PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/46.%20Infections%20neurom%C3%A9ning%C3%A9es.pdf","label":"Collège CE-MIR — Infections neuroméningées (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Syndrome méningé fébrile — Patient entièrement déshabillé — rechercher un purpura","detail":"<h4>CAT — suspicion de <span class=\"kw-alerte\">méningite</span> / <span class=\"kw-clinique\">méningo-encéphalite</span> fébrile — Algorithme d’<span class=\"kw-alerte\">urgence</span> : <span class=\"kw-alerte\">purpura fulminans</span> → CI à la PL → examen direct du <span class=\"kw-bio\">LCS</span></h4>","branches":[{"to":"t-purpura","label":"Purpura fébrile extensif (≥ 1 élément nécrotique ou ecchymotique ≥ 3 mm)","color":"red"},{"to":"q-ci-pl","label":"Pas de purpura fulminans","color":"amber"}]},{"id":"t-purpura","kind":"terminal","label":"Purpura fulminans — urgence vitale","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Purpura</span> fébrile s’étendant en taille et en nombre, <strong>ne s’effaçant pas à la vitropression</strong> ; <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-clinique\">élément nécrotique</span> ou <span class=\"kw-clinique\">ecchymotique</span> de <span class=\"kw-chiffre\">≥ 3 mm</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> IV (ou IM) immédiate AVANT tout prélèvement et tout transfert</li><li><span class=\"kw-ttt\">Ceftriaxone</span> sans <span class=\"kw-ttt\">lidocaïne</span> <span class=\"kw-chiffre\">1 à 2 g</span> adulte / <span class=\"kw-chiffre\">50-100 mg/kg</span> enfant ; à défaut <span class=\"kw-ttt\">céfotaxime</span> (<span class=\"kw-chiffre\">1-2 g</span> / <span class=\"kw-chiffre\">50 mg/kg</span>) ou <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">1 g</span></li><li><span class=\"kw-ttt\">SAMU 15</span> ; <span class=\"kw-ttt\">remplissage vasculaire</span> si <span class=\"kw-alerte\">état de choc</span> ; transfert en <span class=\"kw-ttt\">réanimation</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ci\">Ponction lombaire contre-indiquée</span> (instabilité hémodynamique, <span class=\"kw-alerte\">CIVD</span>)</li><li><span class=\"kw-ci\">Dexaméthasone non indiquée</span> (n’est pas une <span class=\"kw-alerte\">méningite</span> purulente)</li><li>Prélèvements (<span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-bio\">biopsie cutanée</span>) après la mise en route de l’ATB</li></ul><h4>Mesures</h4><ul><li>Précautions <span class=\"kw-ttt\">gouttelettes</span> (levées <span class=\"kw-chiffre\">24 h</span> après ATB efficace)</li><li><span class=\"kw-ttt\">Signalement et déclaration à l’ARS</span> ; <span class=\"kw-ttt\">antibioprophylaxie</span> + <span class=\"kw-ttt\">vaccination</span> des contacts</li></ul>"},{"id":"q-ci-pl","kind":"decision","label":"Contre-indication à la ponction lombaire ? — Instabilité hémodynamique · trouble de l’hémostase · focalisation / HTIC / Glasgow ≤ 11","branches":[{"to":"t-ci-pl","label":"Oui — CI à la PL","color":"amber"},{"to":"q-examen-direct","label":"Non — PL réalisable d’emblée","color":"green"}]},{"id":"t-ci-pl","kind":"terminal","label":"Imagerie cérébrale (TDM) avant la PL","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-bio\">Hémocultures</span> puis <span class=\"kw-ttt\">antibiothérapie probabiliste</span> (<span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">dexaméthasone</span>) AVANT le départ en imagerie</li><li><span class=\"kw-imagerie\">TDM cérébrale non injectée</span> préalable</li><li><span class=\"kw-bio\">PL</span> différée, réalisée après la <span class=\"kw-imagerie\">TDM</span></li></ul><h4>CI neurologiques</h4><ul><li>Crises convulsives persistantes ; signes de processus expansif / <span class=\"kw-alerte\">HTIC</span> (<span class=\"kw-clinique\">déficit focal</span>, <span class=\"kw-clinique\">HLH</span>, <span class=\"kw-clinique\">syndrome cérébelleux</span>) ; <span class=\"kw-alerte\">engagement</span> (<span class=\"kw-chiffre\">Glasgow ≤ 11</span> + souffrance du tronc).</li></ul><h4>CI non neurologiques</h4><ul><li>Infection cutanée au point de <span class=\"kw-ttt\">ponction</span> ; <span class=\"kw-alerte\">instabilité hémodynamique / respiratoire</span> ; trouble de l’hémostase (<span class=\"kw-chiffre\">plaquettes &lt; 50 G/L</span>, <span class=\"kw-chiffre\">TP &lt; 50 %</span>, <span class=\"kw-chiffre\">TCA &gt; 1,5</span>, <span class=\"kw-alerte\">CIVD</span>, <span class=\"kw-ttt\">anticoagulant</span> à dose efficace).</li></ul><h4>Délai ATB</h4><ul><li>Après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> et avant la PL si CI ou hôpital à <span class=\"kw-chiffre\">&gt; 90 min</span>.</li></ul>"},{"id":"q-examen-direct","kind":"decision","label":"Résultat de la PL : examen direct + cytochimie — Aspect du LCS, coloration de Gram, glycorachie","branches":[{"to":"t-pneumo","label":"Diplocoque Gram + (pneumocoque)","color":"amber"},{"to":"t-meningo","label":"Diplocoque Gram − (méningocoque)","color":"amber"},{"to":"t-listeria","label":"Bacille Gram + (Listeria)","color":"amber"},{"to":"t-ed-neg","label":"Examen direct négatif, LCS purulent","color":"amber"},{"to":"t-encephalite","label":"LCS lymphocytaire / panaché + signes encéphalitiques","color":"red"},{"to":"t-virale","label":"LCS clair lymphocytaire normoglycorachique, sans encéphalite","color":"green"}]},{"id":"t-pneumo","kind":"terminal","label":"Méningite à pneumocoque","color":"amber","detail":"<h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G</span> IV (<span class=\"kw-ttt\">céfotaxime</span> ou <span class=\"kw-ttt\">ceftriaxone</span>) + <span class=\"kw-ttt\">dexaméthasone</span> IV.</li></ul><h4><span class=\"kw-ttt\">Dexaméthasone</span></h4><ul><li>Avant la 1<sup>re</sup> injection d’ATB ou ≤ <span class=\"kw-chiffre\">12 h</span> ; <span class=\"kw-chiffre\">10 mg</span> adulte / <span class=\"kw-chiffre\">0,15 mg/kg</span> enfant toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 h</span>, <span class=\"kw-chiffre\">4 jours</span> ; réduit de <span class=\"kw-chiffre\">~50 %</span> décès et séquelles.</li></ul><h4>Durée / <span class=\"kw-def\">surveillance</span></h4><ul><li>Durée <span class=\"kw-chiffre\">10-14 j</span> ; <span class=\"kw-bio\">PL de contrôle</span> si <span class=\"kw-chiffre\">CMI C3G &gt; 0,5 mg/L</span> ; recherche d’une <span class=\"kw-clinique\">brèche ostéo-méningée</span>.</li></ul>"},{"id":"t-meningo","kind":"terminal","label":"Méningite à méningocoque","color":"amber","detail":"<h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">C3G</span> IV + <span class=\"kw-ttt\">dexaméthasone</span> ; relais par <span class=\"kw-ttt\">amoxicilline</span> IV si souche sensible. Durée <span class=\"kw-chiffre\">4-7 j</span>.</li></ul><h4>Mesures entourage</h4><ul><li><span class=\"kw-ttt\">Déclaration obligatoire</span> à l’<span class=\"kw-def\">ARS</span> (signalement + notification)</li><li><span class=\"kw-ttt\">Antibioprophylaxie</span> des contacts : <span class=\"kw-ttt\">rifampicine</span> per os <span class=\"kw-chiffre\">2 j</span> (à défaut <span class=\"kw-ttt\">ceftriaxone</span> / <span class=\"kw-ttt\">ciprofloxacine</span> dose unique)</li><li><span class=\"kw-ttt\">Vaccination</span> des contacts (<span class=\"kw-chiffre\">&lt; 10 j</span>) selon le sérogroupe ; précautions <span class=\"kw-ttt\">gouttelettes</span> <span class=\"kw-chiffre\">24 h</span></li></ul>"},{"id":"t-listeria","kind":"terminal","label":"Neurolistériose","color":"amber","detail":"<h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> (<span class=\"kw-chiffre\">21 j</span>) + <span class=\"kw-ttt\">gentamicine</span> (<span class=\"kw-chiffre\">5 j</span>) ; <span class=\"kw-ttt\">cotrimoxazole</span> si <span class=\"kw-ci\">allergie</span> aux β-lactamines.</li></ul><h4>Pièges</h4><ul><li><span class=\"kw-ci\">Pas de dexaméthasone</span> ; <span class=\"kw-etio\">Listeria</span> est naturellement résistant aux <span class=\"kw-ci\">céphalosporines</span>. <span class=\"kw-ttt\">Déclaration obligatoire</span>.</li></ul>"},{"id":"t-ed-neg","kind":"terminal","label":"LCS purulent, examen direct négatif","color":"amber","detail":"<h4>Sans argument pour <span class=\"kw-etio\">Listeria</span></h4><ul><li><span class=\"kw-ttt\">C3G</span> + <span class=\"kw-ttt\">dexaméthasone</span> (+ <span class=\"kw-ttt\">gentamicine</span> si nourrisson <span class=\"kw-chiffre\">&lt; 3 mois</span>).</li></ul><h4>Avec argument pour <span class=\"kw-etio\">Listeria</span></h4><ul><li><span class=\"kw-def\">Terrain</span>, installation progressive, atteinte rhombencéphalique, ou <span class=\"kw-bio\">LCS</span> panaché hypoglycorachique → <span class=\"kw-ttt\">C3G + amoxicilline + gentamicine</span>.</li></ul><h4>Compléments</h4><ul><li><span class=\"kw-bio\">Antigène pneumocoque</span> puis <span class=\"kw-bio\">PCR méningocoque</span> dans le <span class=\"kw-bio\">LCS</span> ; <span class=\"kw-bio\">biopsie cutanée</span> si <span class=\"kw-clinique\">purpura</span>.</li></ul>"},{"id":"t-encephalite","kind":"terminal","label":"Méningo-encéphalite — urgence thérapeutique","color":"red","detail":"<h4>Clinique</h4><ul><li>Signes neurologiques centraux (<span class=\"kw-clinique\">troubles de la vigilance</span>, <span class=\"kw-clinique\">crises</span>, <span class=\"kw-clinique\">troubles du comportement</span>, <span class=\"kw-clinique\">déficit focal</span>) — évoquer <span class=\"kw-etio\">HSV-1</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Aciclovir</span> IV (vise <span class=\"kw-etio\">HSV-1</span>) + <span class=\"kw-ttt\">amoxicilline</span> IV (vise <span class=\"kw-etio\">Listeria</span>), sans attendre la <span class=\"kw-bio\">PCR HSV</span> ni l’<span class=\"kw-imagerie\">IRM</span>. Si <span class=\"kw-ci\">CI à la PL</span> : <span class=\"kw-ttt\">C3G + aciclovir + amoxicilline</span>.</li></ul><h4>Modalités / <span class=\"kw-def\">suivi</span></h4><ul><li><span class=\"kw-ttt\">Aciclovir</span> IV <span class=\"kw-chiffre\">15-21 j</span>, en <strong>perfusion lente + hydratation</strong> (risque d’<span class=\"kw-alerte\">insuffisance rénale</span>) ; 2<sup>e</sup> <span class=\"kw-bio\">PCR HSV</span> sur <span class=\"kw-bio\">LCS</span> à <span class=\"kw-chiffre\">J4</span>.</li></ul>"},{"id":"t-virale","kind":"terminal","label":"Méningite virale","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement symptomatique</span> (<span class=\"kw-etio\">entérovirus</span> : pas de traitement spécifique) ; <span class=\"kw-ttt\">antirétroviral</span> si <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">VIH</span>.</li></ul><h4>Vigilance</h4><ul><li>Toujours rechercher des signes d’<span class=\"kw-def\">encéphalite</span> → imposeraient un <span class=\"kw-ttt\">aciclovir</span> IV.</li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li>Sortie dès l’étiologie <span class=\"kw-etio\">bactérienne</span> écartée (ex. <span class=\"kw-bio\">PCR entérovirus</span> positive) ; pas de <span class=\"kw-def\">suivi</span> particulier.</li></ul>"}]},"cards":[{"i":"6c5b0cf45a58","n":151,"o":"151-1","u":"Définition","t":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez l'adulte et en pédiatrie, d'un abcès cérébral","q":"Quelle est la définition d'une méningite infectieuse chez l'adulte et en pédiatrie ?","a":"<p>Une méningite est une <strong>réaction inflammatoire de l'espace méningé</strong>, le plus souvent d'origine infectieuse.</p>"},{"i":"79b8ed5cbcee","n":151,"o":"151-1","u":"Définition","t":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez l'adulte et en pédiatrie, d'un abcès cérébral","q":"Quelles sont les deux étapes de constitution d'un abcès cérébral ?","a":"<ul><li>La première étape est la <strong>phase d'encéphalite pré-suppurative</strong>, caractérisée par un centre nécrotique, la présence de germes et un œdème.</li><li>La seconde étape est le <strong>stade d'abcès</strong>, avec la formation d'une capsule de gliose.</li></ul>"},{"i":"87d1f14196fb","n":151,"o":"151-1","u":"Définition","t":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez l'adulte et en pédiatrie, d'un abcès cérébral","q":"Quelle est la définition d'une méningo-encéphalite chez l'adulte et en pédiatrie ?","a":"<p>Une méningo-encéphalite est une <strong>inflammation des méninges ET de l'encéphale</strong>, impliquant une atteinte parenchymateuse associée au processus inflammatoire méningé.</p>"},{"i":"b4585f6329be","n":151,"o":"151-1","u":"Définition","t":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez l'adulte et en pédiatrie, d'un abcès cérébral","q":"Quelle est la définition d'un abcès cérébral ?","a":"<p>Un abcès cérébral est une <strong>collection suppurée développée au sein du parenchyme cérébral</strong>. Il se distingue d'un empyème, qui est une collection suppurée de l'espace sous-dural ou extradura.</p>"},{"i":"0c6329353efa","n":151,"o":"151-10","u":"Examens complémentaires","t":"Connaître l'indication d'une ponction lombaire","q":"Quelles sont les situations qui ne constituent PAS une contre-indication à la ponction lombaire ?","a":"<p>Les situations qui ne sont PAS des contre-indications à la PL sont : les <strong>antiagrégants plaquettaires</strong>, la <strong>confusion isolée</strong>, et les <strong>troubles de vigilance isolés</strong>.</p>"},{"i":"33907ca4bb75","n":151,"o":"151-10","u":"Examens complémentaires","t":"Connaître l'indication d'une ponction lombaire","q":"Quelles sont les informations critiques à obtenir lors d'une ponction lombaire pour l'analyse du liquide céphalo-rachidien (LCR) ?","a":"<p>Lors d'une ponction lombaire, il est indispensable de prélever <strong>2-3 mL de LCR dans au moins 5 tubes</strong>, et de réaliser une <strong>glycémie veineuse concomitante</strong> pour interpréter la glycorachie.</p>"},{"i":"be1caa4d03fd","n":151,"o":"151-10","u":"Examens complémentaires","t":"Connaître l'indication d'une ponction lombaire","q":"Dans quel contexte clinique la ponction lombaire est-elle indiquée en urgence ?","a":"<p>La ponction lombaire (PL) est indiquée en urgence devant toute <strong>suspicion de méningite ou de méningo-encéphalite</strong>.</p>"},{"i":"c901d597ace0","n":151,"o":"151-10","u":"Examens complémentaires","t":"Connaître l'indication d'une ponction lombaire","q":"Quelles sont les contre-indications neurologiques à la réalisation d'une ponction lombaire ?","a":"<p>Les contre-indications neurologiques, imposant une <strong>TDM cérébrale non injectée préalable</strong>, sont :</p><ul><li>Des <strong>crises convulsives persistantes</strong>.</li><li>Des signes de <strong>processus expansif ou d'HTIC</strong> (déficit focal, hémianopsie latérale homonyme (HLH), syndrome cérébelleux, crises focales récentes ou non contrôlées).</li><li>Des signes d'<strong>engagement cérébral</strong> (troubles de vigilance avec Glasgow ≤ 11 et signes de souffrance du tronc).</li></ul>"},{"i":"f00e690f401d","n":151,"o":"151-10","u":"Examens complémentaires","t":"Connaître l'indication d'une ponction lombaire","q":"Quelles sont les contre-indications non neurologiques à la réalisation d'une ponction lombaire ?","a":"<p>Les contre-indications non neurologiques sont :</p><ul><li>Une <strong>infection cutanée étendue</strong> au point de ponction.</li><li>Une <strong>instabilité hémodynamique ou respiratoire</strong> (notamment le purpura fulminans).</li><li>Des <strong>troubles de l'hémostase</strong> : anticoagulation à dose efficace, coagulopathie, thrombopénie &lt; 50 G/L, TP &lt; 50%, TCA &gt; 1,5, ou CIVD.</li></ul>"},{"i":"f42f57b0b095","n":151,"o":"151-10","u":"Examens complémentaires","t":"Connaître l'indication d'une ponction lombaire","q":"Quand une imagerie cérébrale préalable est-elle nécessaire avant de réaliser une ponction lombaire ?","a":"<p>Une imagerie cérébrale (TDM cérébrale non injectée) est nécessaire avant la PL en cas de :</p><ul><li>Signes de <strong>focalisation</strong> ou d'<strong>HTIC</strong>.</li><li><strong>Glasgow ≤ 11</strong>.</li><li>Crises épileptiques <strong>focales ou généralisées après 5 ans</strong>.</li><li>Crises <strong>hémicorporelles avant 5 ans</strong>.</li></ul>"},{"i":"1a3ed0bac899","n":151,"o":"151-11","u":"Examens complémentaires","t":"Connaître l'indication et les objectifs des examens d'imagerie devant une suspicion de méningite, d'une encéphalite ou d'un abcès","q":"Quand l'imagerie cérébrale est-elle indiquée au cours de l'évolution d'une méningite ?","a":"<p>L'imagerie est indiquée au cours de l'évolution d'une méningite si :</p><ul><li>L'évolution est <strong>défavorable à 48-72 heures</strong> (recherche d'abcès, empyème, infarctus, thrombophlébite, hydrocéphalie).</li><li>De <strong>nouveaux signes neurologiques</strong> apparaissent.</li><li>La bactérie isolée est <strong>autre que le pneumocoque ou le méningocoque</strong>.</li><li>Il existe des <strong>antécédents de traumatisme crânien ou de brèche ostéo-méningée</strong>.</li><li>Il s'agit d'une méningite à pneumocoque compliquant une <strong>otite, une sinusite ou une mastoïdite</strong>.</li></ul>"},{"i":"89aa7de03f25","n":151,"o":"151-11","u":"Examens complémentaires","t":"Connaître l'indication et les objectifs des examens d'imagerie devant une suspicion de méningite, d'une encéphalite ou d'un abcès","q":"Dans quel contexte de suspicion de méningite l'imagerie cérébrale (TDM non injectée) est-elle indiquée avant la ponction lombaire (PL) ?","a":"<p>L'imagerie cérébrale est indiquée avant la PL si :</p><ul><li>Il existe une <strong>contre-indication neurologique</strong> à la PL.</li><li>Il y a une suspicion d'<strong>engagement précoce</strong>.</li></ul>"},{"i":"ae9117786cad","n":151,"o":"151-11","u":"Examens complémentaires","t":"Connaître l'indication et les objectifs des examens d'imagerie devant une suspicion de méningite, d'une encéphalite ou d'un abcès","q":"Quel est l'examen d'imagerie de première intention en cas de suspicion d'encéphalite, et quels sont ses objectifs ?","a":"<p>L'<strong>IRM cérébrale injectée</strong> est l'examen de première intention. Ses objectifs sont la recherche de <strong>lésions parenchymateuses</strong>, particulièrement dans les régions <strong>temporales et frontales</strong>, se manifestant par un <strong>hypersignal T2/FLAIR</strong> et une éventuelle <strong>prise de contraste T1 gado</strong>.</p>"},{"i":"c4f5e8d1fc7f","n":151,"o":"151-11","u":"Examens complémentaires","t":"Connaître l'indication et les objectifs des examens d'imagerie devant une suspicion de méningite, d'une encéphalite ou d'un abcès","q":"Une imagerie cérébrale normale (TDM ou IRM) permet-elle d'éliminer le diagnostic de méningite ou d'encéphalite ?","a":"<p>Non, une imagerie cérébrale normale <strong>n'élimine jamais</strong> une encéphalite ni une méningite. Le diagnostic reste avant tout <strong>clinique et biologique</strong>.</p>"},{"i":"cd89df07f24a","n":151,"o":"151-11","u":"Examens complémentaires","t":"Connaître l'indication et les objectifs des examens d'imagerie devant une suspicion de méningite, d'une encéphalite ou d'un abcès","q":"Quel est l'examen d'imagerie de référence pour le diagnostic d'un abcès cérébral, et quelles sont ses caractéristiques typiques ?","a":"<p>L'<strong>IRM cérébrale injectée</strong> est l'examen de référence. Elle met en évidence une <strong>lésion arrondie, bien circonscrite, avec une prise de contraste annulaire en cocarde</strong>. En séquence de diffusion, elle montre une <strong>restriction au centre nécrotique (ADC bas)</strong>, ce qui la distingue d'une nécrose tumorale (ADC haut).</p>"},{"i":"1d18a02ecd10","n":151,"o":"151-12","u":"Identifier une urgence","t":"Connaître les signes cliniques de gravité d'une méningite","q":"Quels sont les signes de gravité cutanés d'une méningite ?","a":"<p>Le signe cutané de gravité d'une méningite est un <strong>purpura extensif</strong>, qui doit être systématiquement recherché sur le patient entièrement déshabillé. Un <strong>purpura fébrile extensif</strong> doit être considéré comme un purpura fulminans jusqu'à preuve du contraire, et justifie une antibiothérapie immédiate.</p>"},{"i":"2e282d211f1d","n":151,"o":"151-12","u":"Identifier une urgence","t":"Connaître les signes cliniques de gravité d'une méningite","q":"Quels sont les signes de gravité hémodynamiques et respiratoires d'une méningite ?","a":"<p>Les signes hémodynamiques et respiratoires de gravité d'une méningite sont :</p><ul><li>Une <strong>instabilité hémodynamique</strong> (sepsis, choc septique).</li><li>Une <strong>détresse respiratoire</strong>.</li><li>La défaillance d'un autre organe.</li></ul>"},{"i":"f111aceec35c","n":151,"o":"151-12","u":"Identifier une urgence","t":"Connaître les signes cliniques de gravité d'une méningite","q":"Quels sont les signes de gravité neurologiques d'une méningite ?","a":"<p>Les signes neurologiques d'une méningite indiquant une gravité sont :</p><ul><li>Un score de Glasgow <strong>≤ 11</strong>.</li><li>Des <strong>signes de focalisation</strong>.</li><li>Des <strong>signes de souffrance du tronc cérébral</strong> (témoignant d'un engagement).</li><li>Un <strong>état de mal convulsif</strong>.</li></ul>"},{"i":"0d1816ac41ea","n":151,"o":"151-13","u":"Identifier une urgence","t":"Identifier un purpura fulminans (voir item 332)","q":"Comment définir cliniquement le purpura fulminans ?","a":"<p>Le purpura fulminans est un <strong>purpura vasculaire ne s'effaçant pas à la vitropression</strong>, dont les éléments s'étendent rapidement en taille et en nombre (en quelques minutes ou heures) et prennent un aspect en carte de géographie, débutant volontiers aux membres inférieurs. Il doit comporter soit <strong>≥ 1 élément nécrotique</strong>, soit <strong>≥ 1 élément ecchymotique de diamètre ≥ 3 mm</strong>.</p>"},{"i":"5a027e5ffe5c","n":151,"o":"151-13","u":"Identifier une urgence","t":"Identifier un purpura fulminans (voir item 332)","q":"Quels sont les pièges diagnostiques du purpura fulminans ?","a":"<p>Les lésions sont violacées ou pâles et peuvent être confondues avec une cyanose des extrémités ou des marbrures, mais elles ne s'effacent pas à la pression. Chez l'enfant, le tableau peut être fruste, avec peu de fièvre voire une hypothermie.</p>"},{"i":"881b6e0a0faa","n":151,"o":"151-13","u":"Identifier une urgence","t":"Identifier un purpura fulminans (voir item 332)","q":"Quel \"dogme\" doit-on retenir face à un purpura fébrile ?","a":"<p>Tout <strong>purpura fébrile est un purpura fulminans jusqu'à preuve du contraire</strong>. Il est une urgence absolue car il évolue rapidement vers un choc septique gravissime.</p>"},{"i":"dd620f6ac355","n":151,"o":"151-13","u":"Identifier une urgence","t":"Identifier un purpura fulminans (voir item 332)","q":"Quels germes sont principalement responsables du purpura fulminans ?","a":"<ul><li>Le <strong>méningocoque</strong> est le plus souvent en cause.</li><li>Le <strong>pneumocoque</strong> est plus rare (notamment chez le splénectomisé, le sujet âgé).</li><li>Les streptocoques, Haemophilus et staphylocoques sont exceptionnels.</li></ul>"},{"i":"1d0aa6e8f524","n":151,"o":"151-14","u":"Prise en charge","t":"Connaître la prise en charge thérapeutique d'un purpura fulminans avec posologie des C3G par voie intraveineuse","q":"Quelle est la conduite à tenir pré-hospitalière immédiate devant un purpura fulminans avec état de choc ?","a":"<p>Devant un purpura fulminans avec état de choc, la prise en charge pré-hospitalière immédiate inclut :</p><ul><li>Appel systématique au <strong>SAMU (15)</strong>.</li><li>Pose d'une <strong>voie veineuse périphérique (VVP)</strong> et <strong>remplissage vasculaire</strong>.</li><li>Administration d'une <strong>antibiothérapie intraveineuse (IV) immédiate</strong> (ou intramusculaire IM à défaut), avant tout prélèvement.</li></ul>"},{"i":"73ad1bdaf04e","n":151,"o":"151-14","u":"Prise en charge","t":"Connaître la prise en charge thérapeutique d'un purpura fulminans avec posologie des C3G par voie intraveineuse","q":"Quelles sont les spécificités de la prise en charge hospitalière du purpura fulminans concernant les prélèvements et les thérapeutiques adjuvantes ?","a":"<p>La prise en charge hospitalière du purpura fulminans comprend :</p><ul><li>Transfert en <strong>réanimation</strong>.</li><li>Poursuite de la <strong>C3G à dose méningée</strong>.</li><li>Réalisation des <strong>prélèvements microbiologiques</strong> après la mise en route de l'antibiothérapie (<strong>hémocultures</strong>, <strong>biopsie cutanée des lésions purpuriques</strong>).</li><li>Un <strong>bilan sanguin complet</strong> (NFS, CRP, ionogramme, bilan hépatique et rénal, coagulation, gazométrie).</li><li>La <strong>ponction lombaire est contre-indiquée</strong> en raison de l'instabilité hémodynamique et des troubles de l'hémostase (CIVD).</li><li>La <strong>dexaméthasone n'est pas indiquée</strong>, le purpura fulminans n'étant pas une méningite purulente.</li><li>Des mesures associées sont mises en place : <strong>précautions gouttelettes</strong> (levées 24h après ATB efficace), <strong>signalement et déclaration à l'ARS</strong>, <strong>antibioprophylaxie et vaccination des sujets contacts</strong>.</li></ul>"},{"i":"7fedae6a211e","n":151,"o":"151-14","u":"Prise en charge","t":"Connaître la prise en charge thérapeutique d'un purpura fulminans avec posologie des C3G par voie intraveineuse","q":"Quels antibiotiques de la classe des C3G sont recommandés pour le traitement pré-hospitalier du purpura fulminans, et à quelles posologies chez l'adulte et l'enfant ?","a":"<p>Les C3G recommandées pour le traitement pré-hospitalier du purpura fulminans sont :</p><ul><li><strong>Ceftriaxone</strong> (sans lidocaïne) : <strong>1 à 2 g</strong> chez l'adulte ; <strong>50-100 mg/kg</strong> chez l'enfant.</li><li><strong>Céfotaxime</strong> (sans lidocaïne), à défaut : <strong>1 à 2 g</strong> chez l'adulte ; <strong>50 mg/kg</strong> chez l'enfant.</li><li>L'<strong>Amoxicilline</strong> peut être utilisée à défaut : <strong>1 g</strong> chez l'adulte.</li></ul>"},{"i":"39f268dadc3a","n":151,"o":"151-15","u":"Prise en charge","t":"Connaître la prise en charge immédiate en cas de suspicion de méningite","q":"Quelle est la conduite à tenir immédiate devant une suspicion de méningite, avant tout résultat d'examen ?","a":"<p>La prise en charge immédiate devant une suspicion de méningite combine :</p><ul><li><strong>Isolement</strong> : précautions gouttelettes avec <strong>masque chirurgical</strong> tant que la méningite à méningocoque n'est pas écartée, ou pendant les 24 premières heures d'antibiothérapie.</li><li>Recherche de <strong>signes de gravité</strong> pour une éventuelle orientation en réanimation.</li><li>Bilan microbiologique et traitement, qui ne doivent pas être retardés.</li></ul>"},{"i":"5acbe05de76e","n":151,"o":"151-15","u":"Prise en charge","t":"Connaître la prise en charge immédiate en cas de suspicion de méningite","q":"Quel est le bilan biologique sanguin à réaliser en cas de suspicion de méningite et quels sont les traitements symptomatiques à envisager ?","a":"<p>Le bilan biologique sanguin comprend :</p><ul><li><strong>NFS</strong> (Numération Formule Sanguine)</li><li><strong>Hémostase</strong></li><li><strong>Glycémie</strong></li><li><strong>Ionogramme</strong> sanguin</li><li><strong>Créatininémie</strong></li><li>Bilan <strong>hépatique</strong></li><li>Dépistage <strong>VIH systématique</strong> (après information du patient).</li></ul><p>Les traitements symptomatiques comprennent :</p><ul><li><strong>Antalgiques</strong></li><li><strong>Antipyrétiques</strong></li><li>Correction des troubles <strong>hémodynamiques</strong></li><li><strong>Anti-épileptiques</strong> si crise convulsive.</li></ul>"},{"i":"8843f73ede94","n":151,"o":"151-15","u":"Prise en charge","t":"Connaître la prise en charge immédiate en cas de suspicion de méningite","q":"Quand l'antibiothérapie doit-elle être débutée après la ponction lombaire en cas de suspicion de méningite ?","a":"<p>L'antibiothérapie doit être débutée :</p><ul><li><strong>Après la PL, sans attendre les résultats</strong>, si le liquide céphalorachidien (LCS) est <strong>macroscopiquement trouble</strong> ou en cas de très forte suspicion de méningite bactérienne.</li><li><strong>En urgence (moins d'une heure) après les résultats</strong> si l'examen direct est positif, l'antigène pneumocoque est positif, ou si un faisceau d'arguments biologiques est en faveur d'une méningite bactérienne.</li></ul>"},{"i":"955fa008d4cf","n":151,"o":"151-15","u":"Prise en charge","t":"Connaître la prise en charge immédiate en cas de suspicion de méningite","q":"Quels sont les examens paracliniques immédiats à réaliser devant une suspicion de méningite ?","a":"<p>Les examens paracliniques immédiats sont :</p><ul><li><strong>Deux hémocultures</strong>.</li><li>Une <strong>ponction lombaire (PL)</strong>.</li><li>L'imagerie cérébrale est rarement nécessaire avant la PL.</li></ul>"},{"i":"ebcb0b6681b9","n":151,"o":"151-15","u":"Prise en charge","t":"Connaître la prise en charge immédiate en cas de suspicion de méningite","q":"Dans quelles situations faut-il débuter l'antibiothérapie avant la réalisation de la ponction lombaire en cas de suspicion de méningite ?","a":"<p>L'antibiothérapie doit être débutée avant la PL dans les situations suivantes :</p><ul><li><strong>Avant les hémocultures et avant la PL</strong> : suspicion de <strong>purpura fulminans</strong> en préhospitalier.</li><li><strong>Après les hémocultures et avant la PL</strong> : <strong>purpura fulminans</strong> pris en charge à l'hôpital.</li><li><strong>Après les hémocultures et avant la PL</strong> : en cas de <strong>contre-indication à la PL</strong>, ou si l'hôpital est situé à <strong>plus de 90 minutes</strong>.</li></ul>"},{"i":"878ea92bdee8","n":151,"o":"151-16","u":"Prise en charge","t":"Connaître les indications et les modalités de l'antibiothérapie probabiliste devant une méningite présumée bactérienne","q":"Quelle est l'antibiothérapie probabiliste indiquée en présence d'un bacille Gram positif à l'examen direct du LCS (Listeria) ?","a":"<p>Devant un bacille Gram positif (Listeria), l'antibiothérapie probabiliste repose sur l'<strong>amoxicilline</strong> associée à la <strong>gentamicine</strong>. Dans ce cas, il n'y a <strong>pas de dexaméthasone</strong>.</p>"},{"i":"8aac18ddb55c","n":151,"o":"151-16","u":"Prise en charge","t":"Connaître les indications et les modalités de l'antibiothérapie probabiliste devant une méningite présumée bactérienne","q":"Quelle est l'antibiothérapie probabiliste recommandée en cas de diplocoque Gram positif identifié à l'examen direct du LCS, suggérant un pneumocoque ?","a":"<p>En cas de diplocoque Gram positif (pneumocoque), l'antibiothérapie probabiliste est une <strong>C3G (céfotaxime ou ceftriaxone) par voie intraveineuse (IV)</strong>, associée à la <strong>dexaméthasone</strong>.</p>"},{"i":"8e42682b970c","n":151,"o":"151-16","u":"Prise en charge","t":"Connaître les indications et les modalités de l'antibiothérapie probabiliste devant une méningite présumée bactérienne","q":"Quelles sont les contre-indications à l'administration de dexaméthasone dans le cadre d'une méningite ?","a":"<p>La dexaméthasone est contre-indiquée en cas de <strong>forte suspicion de neurolistériose</strong> et chez les patients <strong>immunodéprimés</strong>.</p>"},{"i":"99ceefca5f20","n":151,"o":"151-16","u":"Prise en charge","t":"Connaître les indications et les modalités de l'antibiothérapie probabiliste devant une méningite présumée bactérienne","q":"Quelle est la prise en charge antibiotique en cas de LCS purulent avec examen direct négatif et sans argument pour une Listeria ?","a":"<p>Si le LCS est purulent avec un examen direct négatif et sans argument en faveur d'une Listeria, l'antibiothérapie probabiliste est une <strong>C3G</strong> associée à la <strong>dexaméthasone</strong>. Chez le nourrisson de moins de 3 mois, la <strong>gentamicine</strong> doit être ajoutée.</p>"},{"i":"b3c12afe8b3f","n":151,"o":"151-16","u":"Prise en charge","t":"Connaître les indications et les modalités de l'antibiothérapie probabiliste devant une méningite présumée bactérienne","q":"Quand la dexaméthasone est-elle indiquée en cas de méningite bactérienne présumée et quelle est sa posologie ?","a":"<p>La dexaméthasone est indiquée dans les méningites à <strong>pneumocoque</strong> ou <strong>méningocoque</strong> (chez l'adulte), à <strong>pneumocoque</strong> ou <strong>Haemophilus</strong> (chez l'enfant), ou dans toute méningite bactérienne présumée. Elle est administrée par <strong>voie IV</strong>, idéalement avant la première injection d'antibiotique (ou au plus tard dans les 12 heures), pour une durée de <strong>4 jours</strong>.</p>"},{"i":"dbb431cd6c6e","n":151,"o":"151-16","u":"Prise en charge","t":"Connaître les indications et les modalités de l'antibiothérapie probabiliste devant une méningite présumée bactérienne","q":"Comment l'antibiothérapie probabiliste d'une méningite présumée bactérienne est-elle guidée ?","a":"<p>L'antibiothérapie probabiliste d'une méningite présumée bactérienne est guidée principalement par l'<strong>examen direct du liquide céphalo-rachidien (LCS)</strong>.</p>"},{"i":"0aeeef30f6e5","n":151,"o":"151-19","u":"Suivi et/ou Pronostic","t":"Connaître les mesures générales à prendre pour la personne atteinte et son entourage en cas d'infection invasive à méningocoque","q":"En cas d'infection invasive à méningocoque, quelles mesures de protection immédiates doivent être prises pour le patient et par les soignants ?","a":"<p>Des mesures de <strong>précautions gouttelettes</strong> sont nécessaires. Le patient et les soignants doivent porter un <strong>masque chirurgical</strong>. Ces précautions peuvent être levées <strong>24 heures après le début d'une antibiothérapie efficace</strong>.</p>"},{"i":"2c07b6685ceb","n":151,"o":"151-19","u":"Suivi et/ou Pronostic","t":"Connaître les mesures générales à prendre pour la personne atteinte et son entourage en cas d'infection invasive à méningocoque","q":"Quelle est l'attitude à adopter concernant l'éviction des collectivités et la déclaration des cas d'infection invasive à méningocoque ?","a":"<p>Le patient doit être <strong>évincé des collectivités</strong> jusqu'à guérison clinique. La déclaration est <strong>obligatoire</strong> et doit être signalée nominativement à l'<strong>ARS sans délai</strong>, puis notifiée anonymement via un formulaire spécifique.</p>"},{"i":"383ae3f2a00e","n":151,"o":"151-19","u":"Suivi et/ou Pronostic","t":"Connaître les mesures générales à prendre pour la personne atteinte et son entourage en cas d'infection invasive à méningocoque","q":"Quelle est l'antibioprophylaxie recommandée pour les sujets contacts d'une infection invasive à méningocoque et quelles sont les précautions à prendre ?","a":"<p>L'antibioprophylaxie est <strong>urgente</strong>, à administrer dans les <strong>24-48 heures</strong> (au plus tard 10 jours). La molécule de référence est la <strong>rifampicine per os pendant 2 jours</strong>. En cas de contre-indication ou de résistance, la <strong>ceftriaxone</strong> ou la <strong>ciprofloxacine</strong> en dose unique peuvent être utilisées. Il faut informer le patient des effets indésirables de la rifampicine : <strong>coloration orange des urines et des larmes</strong> (attention aux porteurs de lentilles), et <strong>baisse d'efficacité des contraceptifs oraux</strong>. Un nouveau-né dont la mère est traitée doit être supplémenté en <strong>vitamine K</strong>. L'antibioprophylaxie est inutile si le contage a eu lieu après le début de l'antibiothérapie du cas index par C3G.</p>"},{"i":"65e55b1ca84f","n":151,"o":"151-19","u":"Suivi et/ou Pronostic","t":"Connaître les mesures générales à prendre pour la personne atteinte et son entourage en cas d'infection invasive à méningocoque","q":"Quels critères définissent un « sujet contact » nécessitant une antibioprophylaxie dans le cadre d'une infection invasive à méningocoque ?","a":"<p>Un sujet contact est défini par un contact avec les sécrétions oropharyngées du cas index, jugé <strong>direct</strong> (face à face), <strong>proche (< 1 m)</strong> ou <strong>prolongé (> 1 h)</strong> durant les <strong>10 jours précédents</strong>. Cela inclut aussi le <strong>flirt</strong>, les <strong>soignants</strong> ayant réalisé un bouche-à-bouche, une intubation ou une aspiration sans masque, ainsi que <strong>tous les membres vivant sous le même toit</strong>.</p>"},{"i":"5510113fd4cb","n":151,"o":"151-2","u":"Diagnostic positif","t":"Savoir suspecter cliniquement un syndrome méningé fébrile et connaître les particularités sémiologiques en fonction du terrain (enfant, personne âgée)","q":"Quels sont les quatre éléments cliniques qui définissent un syndrome méningé fébrile typique chez l'adulte ?","a":"<p>Un syndrome méningé fébrile typique associe au moins deux des quatre éléments suivants :</p><ul><li>Une <strong>fièvre</strong></li><li>Une <strong>raideur de nuque</strong></li><li>Des <strong>céphalées</strong></li><li>Une <strong>altération de la conscience</strong></li></ul>"},{"i":"5d2433d135de","n":151,"o":"151-2","u":"Diagnostic positif","t":"Savoir suspecter cliniquement un syndrome méningé fébrile et connaître les particularités sémiologiques en fonction du terrain (enfant, personne âgée)","q":"Quelles sont les particularités sémiologiques d'un syndrome méningé fébrile chez le sujet âgé et chez le nourrisson ?","a":"<ul><li>Chez le <strong>sujet âgé</strong>, les signes sont plus <strong>frustes</strong>, le syndrome infectieux est souvent au second plan, et le tableau peut être dominé par des <strong>troubles du comportement</strong> ou des <strong>signes focaux</strong>.</li><li>Chez le <strong>nourrisson</strong>, le syndrome méningé est souvent <strong>trompeur</strong>.</li></ul>"},{"i":"5d36429282ff","n":151,"o":"151-2","u":"Diagnostic positif","t":"Savoir suspecter cliniquement un syndrome méningé fébrile et connaître les particularités sémiologiques en fonction du terrain (enfant, personne âgée)","q":"Quelle particularité sémiologique doit être systématiquement recherchée en cas de suspicion de syndrome méningé fébrile ?","a":"<p>La recherche d'un <strong>purpura</strong> est obligatoire, sur un patient entièrement déshabillé, en raison de son association possible avec une méningite à méningocoque.</p>"},{"i":"893f13cef91e","n":151,"o":"151-2","u":"Diagnostic positif","t":"Savoir suspecter cliniquement un syndrome méningé fébrile et connaître les particularités sémiologiques en fonction du terrain (enfant, personne âgée)","q":"Quelles sont les caractéristiques des céphalées et des vomissements dans le cadre d'un syndrome méningé fébrile ?","a":"<ul><li>Les <strong>céphalées</strong> sont quasi-constantes, précoces, inhabituelles, mal soulagées par les antalgiques habituels. Leur topographie est en casque ou diffuse. Elles sont aggravées par les mouvements de la tête, l'examen, la lumière (<strong>photophobie</strong>) et le bruit (<strong>phonophobie</strong>).</li><li>Les <strong>vomissements</strong> sont inconstants, précoces, souvent en jet et peuvent être favorisés par les changements de position. Ils peuvent parfois soulager les céphalées.</li></ul>"},{"i":"8ed7b88aca80","n":151,"o":"151-2","u":"Diagnostic positif","t":"Savoir suspecter cliniquement un syndrome méningé fébrile et connaître les particularités sémiologiques en fonction du terrain (enfant, personne âgée)","q":"Comment caractérise-t-on la raideur méningée et quels sont les signes associés à rechercher dans un syndrome méningé fébrile ?","a":"<p>La raideur méningée se manifeste par :</p><ul><li>Une <strong>attitude en « chien de fusil »</strong>.</li><li>Une <strong>résistance invincible et douloureuse</strong> à la flexion de la nuque, alors que la rotation et la latéralité sont conservées mais douloureuses.</li><li>Le <strong>signe de Kernig</strong> : la flexion des cuisses sur le bassin, jambes étendues, oblige à fléchir les jambes.</li><li>Le <strong>signe de Brudzinski</strong> : la flexion passive de la nuque entraîne la flexion des deux membres inférieurs ; la flexion passive d'une hanche entraîne celle du membre inférieur controlatéral.</li></ul><p>Il faut également rechercher des signes comme la <strong>raie méningitique de Trousseau</strong>, une <strong>hyperesthésie cutanée diffuse</strong>, et des <strong>ROT vifs</strong>.</p>"},{"i":"2f9828ec30b3","n":151,"o":"151-20","u":"Définition","t":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez le nouveau né et le nourrisson","q":"Quelle est l'incidence des méningites bactériennes chez l'enfant par rapport à l'adulte ?","a":"<p>L'incidence des méningites bactériennes est <strong>beaucoup plus élevée chez l'enfant</strong> que chez l'adulte.</p>"},{"i":"327265955956","n":151,"o":"151-20","u":"Définition","t":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez le nouveau né et le nourrisson","q":"Comment définit-on une méningite infectieuse chez le nouveau-né et le nourrisson ?","a":"<p>Une méningite infectieuse chez le nouveau-né et le nourrisson correspond à une <strong>réaction inflammatoire de l'espace méningé</strong>, le plus souvent d'origine infectieuse.</p>"},{"i":"d7b160773a21","n":151,"o":"151-20","u":"Définition","t":"Connaître la définition des méningites et méningo-encéphalites infectieuses chez le nouveau né et le nourrisson","q":"En quoi le syndrome méningé est-il particulier chez le nourrisson ?","a":"<p>Chez le nourrisson, le syndrome méningé est souvent <strong>trompeur ou fruste</strong>. Le tableau clinique peut se limiter à des signes peu spécifiques comme une <ul><li>obnubilation</li><li>asthénie</li><li>troubles du comportement</li></ul>.</p>"},{"i":"505ccd4f70cf","n":151,"o":"151-3","u":"Diagnostic positif","t":"Savoir identifier les éléments d'un syndrome encéphalitique et savoir évoquer une méningo-encéphalite herpétique","q":"Quand faut-il évoquer une méningo-encéphalite herpétique ?","a":"<p>La méningo-encéphalite herpétique (dont HSV est la <strong>1ère cause d'encéphalite virale</strong>) doit être évoquée devant :</p><ul><li>Toute <strong>céphalée fébrile</strong>.</li><li>Toute <strong>confusion fébrile</strong>.</li><li>Tout <strong>coma fébrile</strong>.</li><li>Tout tableau <strong>neurologique aigu ou subaigu fébrile polymorphe</strong>.</li></ul><p>C'est une <strong>urgence diagnostique et thérapeutique</strong>.</p>"},{"i":"86004d543fcf","n":151,"o":"151-3","u":"Diagnostic positif","t":"Savoir identifier les éléments d'un syndrome encéphalitique et savoir évoquer une méningo-encéphalite herpétique","q":"Quels sont les signes cliniques caractéristiques d'un syndrome encéphalitique ?","a":"<ul><li><strong>Troubles de la vigilance</strong> : quasi-constants, fluctuants, allant de l'obnubilation au coma, souvent associés à des troubles neurovégétatifs.</li><li><strong>Manifestations épileptiques</strong> : plus souvent partielles que généralisées, avec possibilité d'état de mal. Elles sont fréquemment temporales dans l'herpès (illusions, hallucinations olfactives, gustatives ou auditives).</li><li><strong>Troubles des fonctions supérieures</strong> : syndrome confusionnel, bradypsychie, troubles du comportement, troubles mnésiques (oubli à mesure), troubles du langage (manque du mot, aphasie amnésique).</li><li><strong>Autres</strong> : mouvements anormaux, signes de focalisation (déficit moteur, atteinte des nerfs crâniens).</li></ul>"},{"i":"b7db1f586cc1","n":151,"o":"151-3","u":"Diagnostic positif","t":"Savoir identifier les éléments d'un syndrome encéphalitique et savoir évoquer une méningo-encéphalite herpétique","q":"Quel est le signe radiologique typique d'une méningo-encéphalite herpétique à l'IRM ?","a":"<p>L'IRM, et plus précisément la séquence FLAIR, révèle un <strong>hypersignal temporal interne</strong>, qui signe une atteinte limbique caractéristique de la méningo-encéphalite herpétique.</p>"},{"i":"f456a760f59a","n":151,"o":"151-3","u":"Diagnostic positif","t":"Savoir identifier les éléments d'un syndrome encéphalitique et savoir évoquer une méningo-encéphalite herpétique","q":"Comment distinguer cliniquement un syndrome encéphalitique d'une méningite ?","a":"<p>Le syndrome encéphalitique se caractérise par la présence de <strong>signes neurologiques centraux</strong>, absents dans une méningite pure. Cette distinction est uniquement clinique, et jamais basée sur l'analyse du Liquide Céphalo-Rachidien (LCR).</p>"},{"i":"0b14d39e4e3c","n":151,"o":"151-7","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie bactériennes et virales des méningites en fonction de l'analyse cytochimique du liquide cérébro-spinal (LCS) et de l'âge du patient","q":"Quels sont les principaux germes bactériens responsables de méningites en fonction de l'âge du patient ?","a":"<p>Les principaux germes bactériens varient avec l'âge :</p><ul><li><strong>< 2-3 mois</strong> : <strong>Streptocoque du groupe B</strong> (constamment sensible à l'amoxicilline) puis E. coli.</li><li><strong>2-12 mois</strong> : <strong>Pneumocoque</strong>.</li><li><strong>1-24 ans</strong> : <strong>Méningocoque</strong>.</li><li><strong>> 24 ans</strong> : <strong>Pneumocoque</strong>.</li><li>Chez l'adulte, les trois bactéries les plus fréquentes sont le <strong>Pneumocoque</strong> (50-55 %), le <strong>Méningocoque</strong> (25-30 %) et <strong>Listeria monocytogenes</strong> (5-10 % en particulier chez le sujet > 50 ans, la femme enceinte, l'alcoolique et l'immunodéprimé).</li></ul>"},{"i":"2ead0e4064f4","n":151,"o":"151-7","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie bactériennes et virales des méningites en fonction de l'analyse cytochimique du liquide cérébro-spinal (LCS) et de l'âge du patient","q":"Quelles sont les caractéristiques des 3 principales bactéries responsables de méningites purulentes chez l'adulte ?","a":"<p>Elles sont :</p><ul><li><strong>Pneumocoque</strong> : 50-55 % des cas, portage voies aériennes supérieures (VAS), <strong>cocci Gram positif</strong> en diplocoque ou en chaînette.</li><li><strong>Méningocoque</strong> : 25-30 % des cas, portage rhinopharyngé, <strong>cocci Gram négatif</strong> en diplocoque. Les sérogroupes B, C, W, Y sont les plus fréquents.</li><li><strong>Listeria monocytogenes</strong> : 5-10 % des cas, <strong>bacille Gram positif</strong>, principalement chez le sujet > 50 ans, la femme enceinte, l'alcoolique ou l'immunodéprimé. Elle est souvent associée à des méningites à liquide clair avec hypoglycorachie.</li></ul>"},{"i":"51c890e1d040","n":151,"o":"151-7","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie bactériennes et virales des méningites en fonction de l'analyse cytochimique du liquide cérébro-spinal (LCS) et de l'âge du patient","q":"Comment l'analyse cytochimique du LCS permet-elle d'orienter le diagnostic étiologique d'une méningite purulente bactérienne ?","a":"<p>Une méningite purulente bactérienne se caractérise par :</p><ul><li>Un LCS macroscopiquement <strong>trouble</strong>.</li><li>Une cytologie avec <strong>plus de 1000 cellules/mm³, à nette prédominance de PNN</strong>.</li><li>Une <strong>hypoglycorachie ≤ 0,4 × glycémie</strong> (sensibilité de 80 %, spécificité de 98 % pour une étiologie bactérienne).</li><li>Une <strong>hyperprotéinorachie > 1 g/L</strong>.</li><li>Un <strong>lactatorachie > 3,2 mmol/L</strong>.</li><li>Un examen direct du LCS <strong>positif dans 60-80 % des cas</strong> en l'absence d'antibiothérapie préalable.</li></ul>"},{"i":"56670b6b55c9","n":151,"o":"151-7","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie bactériennes et virales des méningites en fonction de l'analyse cytochimique du liquide cérébro-spinal (LCS) et de l'âge du patient","q":"Quelles sont les principales caractéristiques cytochimiques du LCS orientant vers une méningite à liquide clair virale ?","a":"<p>Une méningite à liquide clair virale présente généralement :</p><ul><li>Un LCS macroscopiquement <strong>clair</strong>.</li><li>Une cytologie avec <strong>5-100 cellules/mm³</strong> (parfois 100-1000), à <strong>prédominance lymphocytaire</strong> ou formule panachée. Il est à noter qu'environ <strong>30 % des méningites virales (notamment entérovirus) peuvent avoir une formule purulente (à PNN) dans les 24 premières heures</strong>.</li><li>Une <strong>normoglycorachie</strong>.</li><li>Une <strong>protéinorachie modérée (< 1 g/L)</strong>.</li><li>Un <strong>lactatorachie < 3,2 mmol/L</strong>.</li><li>Un examen direct du LCS <strong>négatif</strong>.</li></ul>"},{"i":"8765b739f122","n":151,"o":"151-7","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie bactériennes et virales des méningites en fonction de l'analyse cytochimique du liquide cérébro-spinal (LCS) et de l'âge du patient","q":"Quelles sont les causes de méningites à liquide clair avec hypoglycorachie ?","a":"<p>Les méningites à liquide clair associées à une hypoglycorachie (hypoglycorachie ≤ 0,4 × glycémie) orientent vers des étiologies spécifiques :</p><ul><li><strong>Listériose</strong> (<em>Listeria monocytogenes</em>).</li><li><strong>Tuberculose</strong>.</li><li><strong>Cryptococcus neoformans</strong>.</li></ul>"},{"i":"2449d4c053de","n":151,"o":"151-8","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie infectieuse des méningo-encéphalites","q":"Quels sont les principaux agents viraux responsables de méningo-encéphalites, au-delà de l'HSV-1 ?","a":"<ul><li>Autres herpèsvirus : <strong>HSV-2, CMV, VZV, EBV, HHV-6</strong></li><li><strong>Entérovirus</strong></li><li><strong>VIH</strong> (primo-infection)</li><li><strong>Rage</strong></li><li><strong>Arbovirus</strong> (West-Nile, encéphalite japonaise, tick-borne encephalitis)</li></ul>"},{"i":"37cbccf58bba","n":151,"o":"151-8","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie infectieuse des méningo-encéphalites","q":"Quelle est la part des méningo-encéphalites dont l'agent causal n'est pas identifié ?","a":"<p>L'agent causal d'une méningo-encéphalite n'est pas identifié dans <strong>plus de 50 %</strong> des cas.</p>"},{"i":"703d08f2d841","n":151,"o":"151-8","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie infectieuse des méningo-encéphalites","q":"Quels sont les trois agents causaux de méningo-encéphalite curables qui imposent un diagnostic et un traitement précoces ?","a":"<ul><li><strong>HSV</strong> (Herpes Simplex Virus)</li><li><strong>Listeria</strong> (Listeria monocytogenes)</li><li><strong>BK</strong> (Mycobacterium tuberculosis, tuberculose)</li></ul>"},{"i":"add36d495c0e","n":151,"o":"151-8","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie infectieuse des méningo-encéphalites","q":"Quels sont les trois mécanismes principaux des encéphalites ?","a":"<ul><li><strong>Invasif direct</strong> (infection du parenchyme, typiquement la méningo-encéphalite herpétique)</li><li><strong>Post-infectieux ou post-vaccinal</strong> (ADEM, processus immunologique à distance)</li><li><strong>Auto-immun non infectieux</strong></li></ul>"},{"i":"ea42708ff1a7","n":151,"o":"151-8","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie infectieuse des méningo-encéphalites","q":"Quelles sont les étiologies bactériennes et parasitaires des méningo-encéphalites ?","a":"<ul><li><strong>Bactéries</strong> : Tuberculose, <strong>Listeria monocytogenes</strong>, <strong>Borrelia</strong> (Lyme), syphilis, leptospirose, Mycoplasma pneumoniae.</li><li><strong>Parasites</strong> : <strong>Plasmodium falciparum</strong> (neuropaludisme), toxoplasmose.</li></ul>"},{"i":"f34a9d160ec1","n":151,"o":"151-8","u":"Étiologies","t":"Connaître les principales étiologies et l'épidémiologie infectieuse des méningo-encéphalites","q":"Quel virus représente la première cause de méningo-encéphalite à liquide clair, et quelle est sa fréquence ?","a":"<p>L'<strong>HSV</strong> (Herpes Simplex Virus) est la première cause de méningo-encéphalite à liquide clair, représentant environ <strong>25 %</strong> des cas.</p>"}]};